INSERT INTO question_sets (id, slug, title, description, detail, total_questions)
INSERT INTO questions
  (id, set_id, sort_order, topic, difficulty, prompt, correct_option, explanation, terms)
VALUES
(1, 1, 1, 'LLM, Transformer, Token & API', 'Dễ', 'Mối quan hệ nào mô tả đúng AI và Machine Learning?', 'B', 'Machine Learning nằm trong phạm vi rộng hơn của Artificial Intelligence và học quy luật từ dữ liệu.', '**Artificial Intelligence**: AI — trí tuệ nhân tạo; lĩnh vực tạo hệ thống có khả năng thực hiện nhiệm vụ thường cần trí tuệ con người.; **Machine Learning**: ML — học máy; nhánh AI học quy luật từ dữ liệu thay vì chỉ dùng luật viết sẵn.'),
(2, 1, 2, 'LLM, Transformer, Token & API', 'Dễ', 'Discriminative AI thường được dùng để làm việc gì?', 'C', 'Slide phân biệt Discriminative AI với Generative AI: nhóm đầu chủ yếu phân loại và dự đoán.', '**discriminative**: mô hình phân biệt; thường phân loại hoặc dự đoán nhãn đã định.; **generative**: mô hình tạo sinh; có khả năng tạo nội dung mới từ mẫu đã học.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(3, 1, 3, 'LLM, Transformer, Token & API', 'Dễ', 'Generative AI có đặc điểm chính nào?', 'D', 'Generative AI sinh văn bản, hình ảnh hoặc nội dung mới thay vì chỉ chọn nhãn.', '**generative**: mô hình tạo sinh; có khả năng tạo nội dung mới từ mẫu đã học.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(4, 1, 4, 'LLM, Transformer, Token & API', 'Dễ', 'LLM được mô tả đúng nhất là gì?', 'A', 'Slide định nghĩa LLM là mô hình ngôn ngữ lớn dựa trên Transformer và dữ liệu văn bản quy mô lớn.', '**Transformer**: kiến trúc mạng dùng attention để xử lý quan hệ giữa các token trong chuỗi.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(5, 1, 5, 'LLM, Transformer, Token & API', 'Dễ', 'Transformer xử lý chuỗi bằng cơ chế cốt lõi nào?', 'C', 'Self-attention cho phép mô hình cân nhắc quan hệ giữa các token trong cùng ngữ cảnh.', '**self-attention**: cơ chế để mỗi token cân nhắc mức liên quan với các token khác trong cùng context.; **Transformer**: kiến trúc mạng dùng attention để xử lý quan hệ giữa các token trong chuỗi.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(6, 1, 6, 'LLM, Transformer, Token & API', 'Dễ', 'Token trong LLM là gì?', 'D', 'Token có thể là từ, một phần từ hoặc ký hiệu; đây là đơn vị tính toán và tính phí.', '**token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(7, 1, 7, 'LLM, Transformer, Token & API', 'Dễ', 'Next-token prediction nghĩa là mô hình làm gì?', 'A', 'LLM sinh văn bản tuần tự bằng cách ước lượng xác suất cho token tiếp theo.', '**next-token prediction**: dự đoán token tiếp theo dựa trên các token đã có.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(8, 1, 8, 'LLM, Transformer, Token & API', 'Dễ', 'Pre-training có vai trò gì trong quy trình tạo LLM?', 'B', 'Pre-training là giai đoạn mô hình đọc dữ liệu quy mô lớn để học biểu diễn ngôn ngữ và kiến thức.', '**pre-training**: huấn luyện trước trên dữ liệu lớn để học ngôn ngữ và tri thức nền.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(9, 1, 9, 'LLM, Transformer, Token & API', 'Dễ', 'Knowledge cutoff của LLM nói lên điều gì?', 'D', 'Nếu không có retrieval hoặc công cụ cập nhật, LLM không tự biết sự kiện sau thời điểm training.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(10, 1, 10, 'LLM, Transformer, Token & API', 'Dễ', 'Trong cách tính phí API, tổng token thường gồm thành phần nào?', 'C', 'Slide Token Economy nêu tổng chi phí dựa trên token đầu vào và token đầu ra.', '**token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(11, 1, 11, 'LLM, Transformer, Token & API', 'Vừa', 'Một prompt giữ nguyên output nhưng tăng gấp đôi phần context. Tác động hợp lý nhất là gì?', 'B', 'Input token nhiều hơn làm tăng chi phí và thời gian xử lý, dù số token output không đổi.', '**context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(12, 1, 12, 'LLM, Transformer, Token & API', 'Vừa', 'Với tác vụ phân loại cần kết quả ổn định, lựa chọn nào phù hợp hơn?', 'C', 'Slide khuyên bắt đầu temperature=0 cho code, phân tích hoặc tác vụ cần tính tất định hơn.', '**temperature**: tham số sampling điều khiển mức đa dạng/ngẫu nhiên của output.'),
(13, 1, 13, 'LLM, Transformer, Token & API', 'Vừa', 'Một request vừa có input vừa có output token. Context window cần tính đến gì?', 'D', 'Context window là số token tối đa mô hình xử lý trong một lần gọi, gồm input và output.', '**context window**: cửa sổ ngữ cảnh; tổng số token model có thể xử lý trong một lần gọi.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(14, 1, 14, 'LLM, Transformer, Token & API', 'Vừa', 'Streaming response cải thiện trải nghiệm chủ yếu bằng cách nào?', 'A', 'Streaming giảm cảm giác chờ bằng cách gửi chunk sớm; nó không tự giảm token hay lỗi nội dung.', '**streaming**: trả kết quả từng phần ngay khi sinh, thay vì chờ toàn bộ output.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(15, 1, 15, 'LLM, Transformer, Token & API', 'Vừa', 'Khi chọn giữa model rẻ và model mạnh, nguyên tắc thực dụng nào đúng?', 'C', 'Framework chọn model cân bằng chất lượng, latency và chi phí theo độ khó của task.', '**latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(16, 1, 16, 'LLM, Transformer, Token & API', 'Vừa', 'Tự host LLM giúp kiểm soát điều gì nhưng phải gánh thêm gì?', 'D', 'Self-host tăng quyền kiểm soát và riêng tư nhưng đổi lại là chi phí, hạ tầng và vận hành.', '**LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(17, 1, 17, 'LLM, Transformer, Token & API', 'Vừa', 'Một API wrapper tốt nên tách phần nào ra khỏi code nghiệp vụ?', 'A', 'Wrapper giúp chuẩn hóa provider, cấu hình và theo dõi usage để code ứng dụng gọn hơn.', '**token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(18, 1, 18, 'LLM, Transformer, Token & API', 'Vừa', 'Nếu tăng top_p hoặc temperature trong task sáng tạo, kết quả thường thay đổi thế nào?', 'B', 'Các tham số sampling cao hơn thường mở rộng lựa chọn token; cần cân bằng với tính ổn định.', '**temperature**: tham số sampling điều khiển mức đa dạng/ngẫu nhiên của output.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **top_p**: tham số giới hạn tập token có xác suất tích lũy cao được dùng khi sampling.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(19, 1, 19, 'LLM, Transformer, Token & API', 'Vừa', 'Tại sao prompt dài có thể làm output kém dù model có context lớn?', 'D', 'Day 4 nhấn mạnh token thừa vừa tốn chi phí vừa có thể làm model khó tập trung.', '**context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(20, 1, 20, 'LLM, Transformer, Token & API', 'Vừa', 'Vibe coding vẫn cần bước nào sau khi AI sinh code?', 'C', 'Workflow của Vibe Coding là Idea → Prompt → Code → Test → Refine, không dừng ở việc sinh code.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(21, 1, 21, 'LLM, Transformer, Token & API', 'Khó', 'Trong self-attention, nếu query của token hiện tại tương đồng cao với key của một token khác, điều gì có xu hướng xảy ra?', 'B', 'Q·K tạo attention score; sau scaling và softmax, score cao làm value tương ứng đóng góp nhiều hơn.', '**self-attention**: cơ chế để mỗi token cân nhắc mức liên quan với các token khác trong cùng context.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(22, 1, 22, 'LLM, Transformer, Token & API', 'Khó', 'Vì sao scaled dot-product attention chia score cho căn bậc hai của số chiều key?', 'C', 'Scaling giúp gradient và phân phối softmax ổn định hơn khi vector có nhiều chiều.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(23, 1, 23, 'LLM, Transformer, Token & API', 'Khó', 'Decoder-only Transformer cần masked self-attention vì lý do nào?', 'D', 'Causal mask bảo đảm quá trình next-token prediction không nhìn trước đáp án tương lai.', '**next-token prediction**: dự đoán token tiếp theo dựa trên các token đã có.; **self-attention**: cơ chế để mỗi token cân nhắc mức liên quan với các token khác trong cùng context.; **Transformer**: kiến trúc mạng dùng attention để xử lý quan hệ giữa các token trong chuỗi.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(24, 1, 24, 'LLM, Transformer, Token & API', 'Khó', 'Một prompt tiếng Việt dài hơn prompt tiếng Anh cùng nghĩa có thể làm cost cao hơn vì sao?', 'A', 'Tokenization không đồng nhất giữa ngôn ngữ; số token, không phải số từ trực tiếp, quyết định cost.', '**prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(25, 1, 25, 'LLM, Transformer, Token & API', 'Khó', 'Nếu system prompt chiếm 20%, retrieved context 60% và phần còn lại dành cho query/output, thiết kế này đang làm gì?', 'B', 'Day 8 đưa ví dụ phân bổ 20/60/20 để tránh nhồi context đến sát giới hạn.', '**system prompt**: chỉ dẫn nền do ứng dụng đặt để định nghĩa vai trò, luật và capability của model.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(26, 1, 26, 'LLM, Transformer, Token & API', 'Khó', 'Một chatbot có 1.000 lượt/ngày, mỗi lượt 500 input và 200 output token. Công thức cost đúng nhất là gì?', 'C', 'Chi phí phải nhân số lượt với token từng loại rồi áp đơn giá input và output riêng.', '**chatbot**: hệ thống hội thoại thường trả lời bằng văn bản theo context của lượt chat.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(27, 1, 27, 'LLM, Transformer, Token & API', 'Khó', 'Vì sao temperature=0 vẫn không đồng nghĩa hệ thống luôn đúng?', 'D', 'Tính ổn định của sampling không tạo thêm evidence hoặc loại bỏ lỗi kiến trúc.', '**temperature**: tham số sampling điều khiển mức đa dạng/ngẫu nhiên của output.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(28, 1, 28, 'LLM, Transformer, Token & API', 'Khó', 'Một request FAQ đơn giản và một request reasoning nhiều bước nên có chiến lược model nào?', 'A', 'Framework chọn model theo task, ưu tiên cost/latency khi chất lượng model nhỏ đã đủ.', '**reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(29, 1, 29, 'LLM, Transformer, Token & API', 'Khó', 'SFT đứng ở đâu trong chuỗi tạo model usable?', 'B', 'Slide tóm tắt Pre-training → SFT → RLHF/DPO; mỗi bước phục vụ một mục tiêu khác.', '**pre-training**: huấn luyện trước trên dữ liệu lớn để học ngôn ngữ và tri thức nền.; **RLHF**: Reinforcement Learning from Human Feedback — học tăng cường từ phản hồi của con người.; **SFT**: Supervised Fine-Tuning — tinh chỉnh có giám sát bằng các ví dụ input-output.; **DPO**: Direct Preference Optimization — tối ưu trực tiếp theo cặp câu trả lời được con người ưa thích.'),
(30, 1, 30, 'LLM, Transformer, Token & API', 'Khó', 'Embedding của câu hỏi và token embedding trong Transformer khác nhau ở điểm nào?', 'C', 'Token embedding là đầu vào nội bộ Transformer; embedding model phục vụ so sánh ngữ nghĩa cho retrieval.', '**Transformer**: kiến trúc mạng dùng attention để xử lý quan hệ giữa các token trong chuỗi.; **embedding**: vector số biểu diễn ngữ nghĩa của văn bản, hình ảnh hoặc dữ liệu khác.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.'),
(31, 1, 31, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Tư duy problem-first yêu cầu nhóm làm gì trước?', 'B', 'Day 2 nhấn mạnh không giải quyết vội giải pháp được yêu cầu; cần tìm đúng vấn đề trước.', '**AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(32, 1, 32, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Trong ví dụ ''muốn xây chatbot'', câu hỏi đầu tiên nên là gì?', 'C', '''Chatbot'' có thể che nhiều bài toán khác nhau như FAQ, routing, QA hoặc phân tích cảm xúc.', '**chatbot**: hệ thống hội thoại thường trả lời bằng văn bản theo context của lượt chat.'),
(33, 1, 33, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Double Diamond giúp nhóm cân bằng hai hoạt động nào?', 'D', 'Hai hình thoi lần lượt giúp tìm đúng vấn đề và tìm đúng giải pháp.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(34, 1, 34, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Observation trong Human-Centered Design tập trung vào điều gì?', 'A', 'HCD bắt đầu từ việc quan sát đối tượng mục tiêu và workflow thực tế của họ.', '**observation**: quan sát; kết quả tool hoặc môi trường trả lại cho agent.; **workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.'),
(35, 1, 35, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Baseline có ý nghĩa gì khi đánh giá một ý tưởng AI?', 'C', 'Không có baseline thì khó biết AI cải thiện điều gì so với rule hoặc quy trình thủ công.', '**baseline**: mốc chuẩn dùng để so sánh với cách làm hiện tại.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(36, 1, 36, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Một problem statement tốt nên giúp suy ra được gì?', 'D', 'Problem statement tốt nối vấn đề kinh doanh với tiêu chí eval và boundary kỹ thuật.', '**problem statement**: mô tả bài toán rõ actor, pain point, metric, boundary và cách đánh giá.; **eval**: viết tắt của evaluation — đánh giá chất lượng AI.'),
(37, 1, 37, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', '''No eval path'' là anti-pattern nào?', 'A', 'No eval path khiến nhóm không có cách đo chất lượng hoặc quyết định deploy.', '**eval**: viết tắt của evaluation — đánh giá chất lượng AI.'),
(38, 1, 38, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Framework Rule / Workflow / Agent khuyên bắt đầu từ đâu?', 'B', 'Day 2 khuyên chỉ tăng độ phức tạp khi giá trị tăng lớn hơn chi phí và rủi ro.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(39, 1, 39, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Data flywheel trong AI product mô tả vòng cải thiện nào?', 'D', 'Feedback từ production có thể quay lại làm dữ liệu và cải thiện hệ thống qua nhiều vòng.', '**AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(40, 1, 40, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Quyết định ''No-Go'' hợp lý khi nào?', 'C', 'Go/No-Go cần dựa vào problem, metric, baseline và rủi ro chứ không chỉ dựa vào demo.', '**baseline**: mốc chuẩn dùng để so sánh với cách làm hiện tại.; **eval**: viết tắt của evaluation — đánh giá chất lượng AI.'),
(41, 1, 41, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Prototype dùng để làm gì trong AI product?', 'B', 'Prototype giúp học nhanh từ giả thuyết rẻ nhất trước khi build đầy đủ.', '**prototype**: bản mẫu nhanh để kiểm tra giả thuyết trước khi build đầy đủ.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(42, 1, 42, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Low-fidelity prototype thường giúp kiểm tra điều gì?', 'C', 'Low-fidelity phù hợp để kiểm tra workflow; high-fidelity mới gần trải nghiệm thật hơn.', '**prototype**: bản mẫu nhanh để kiểm tra giả thuyết trước khi build đầy đủ.; **workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.'),
(43, 1, 43, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Wizard of Oz MVP có đặc điểm nào?', 'D', 'Wizard of Oz kiểm tra nhu cầu bằng trải nghiệm giống AI nhưng phần xử lý có thể thủ công.', '**MVP**: Minimum Viable Product — sản phẩm tối thiểu nhưng dùng được để kiểm chứng giả thuyết.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(44, 1, 44, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Trong PRD cho AI feature, problem statement nên tránh điều gì?', 'A', 'Day 5 nhắc problem statement nên nói về vấn đề của user, không giả định AI là đáp án.', '**problem statement**: mô tả bài toán rõ actor, pain point, metric, boundary và cách đánh giá.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(45, 1, 45, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Non-goals trong PRD dùng để làm gì?', 'C', 'Non-goals giúp kiểm soát kỳ vọng và tránh mở rộng scope ngoài mục tiêu.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(46, 1, 46, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Augmentation khác automation ở điểm nào?', 'D', 'Mức agency nên chọn theo độ chắc chắn và cost-of-error của hành động.', '**augmentation**: AI hỗ trợ con người, còn người dùng giữ quyền quyết định cuối.; **automation**: AI tự thực hiện phần lớn hoặc toàn bộ workflow theo quy tắc đã định.'),
(47, 1, 47, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Khi cost-of-error rất cao, thiết kế phù hợp thường là gì?', 'A', 'Với hành động khó hoàn tác, friction của phê duyệt là cơ chế kiểm soát hữu ích.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(48, 1, 48, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Precision cao ưu tiên giảm loại lỗi nào?', 'B', 'Precision quan tâm trong các kết quả được dự đoán là dương tính, nên nhạy với false positive.', '**false positive**: báo nhầm một trường hợp tốt/thấp rủi ro thành trường hợp dương tính.; **precision**: tỷ lệ kết quả được dự đoán dương tính mà thực sự đúng.; **recall**: tỷ lệ các trường hợp đúng mà hệ thống tìm được.'),
(49, 1, 49, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Recall cao ưu tiên giảm loại lỗi nào?', 'D', 'Recall đo mức bao phủ các trường hợp đúng, nên cần giảm bỏ sót.', '**false negative**: bỏ sót một trường hợp thực sự cần được phát hiện.; **precision**: tỷ lệ kết quả được dự đoán dương tính mà thực sự đúng.; **recall**: tỷ lệ các trường hợp đúng mà hệ thống tìm được.'),
(50, 1, 50, 'AI Product, Problem Framing, UX & Evaluation', 'Dễ', 'Vibe check trong eval AI có hạn chế nào?', 'C', 'Demo mượt vài câu không thay thế được bộ case đại diện và quy trình đánh giá lặp lại.', '**eval**: viết tắt của evaluation — đánh giá chất lượng AI.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(51, 1, 51, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Tác vụ lặp lại, biến thể vừa phải, cần hiểu ngôn ngữ nhưng chưa cần hành động nhiều bước nên bắt đầu ở đâu?', 'B', 'AI phù hợp với tác vụ có biến thể vừa phải; chưa cần tăng lên agent nếu workflow có thể kiểm soát.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(52, 1, 52, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Stakeholder nói ''hãy làm agent'', nhưng chưa mô tả pain point. Bước đầu nên là gì?', 'C', 'Discovery interview cần làm rõ vấn đề, tần suất, workflow và cost trước khi chọn kiến trúc.', '**stakeholder**: bên liên quan hoặc người có lợi ích/quyền quyết định trong bài toán.; **workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **actor**: tác nhân trực tiếp thực hiện hoặc chịu ảnh hưởng bởi workflow.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(53, 1, 53, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Nếu chưa có baseline thủ công, nhóm khó kết luận điều gì?', 'D', 'Baseline là điểm tham chiếu để đo giá trị tăng thêm của AI.', '**baseline**: mốc chuẩn dùng để so sánh với cách làm hiện tại.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(54, 1, 54, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Một workflow có các bước cố định nhưng cần LLM ở hai bước khác nhau. Pattern nào phù hợp?', 'A', 'Prompt chaining tách task tuần tự và có thể kiểm tra output trước khi đi tiếp.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(55, 1, 55, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Khi intent quyết định người xử lý chuyên biệt, pattern routing hữu ích vì sao?', 'C', 'Routing giảm prompt phức tạp bằng cách phân luồng theo loại yêu cầu.', '**prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.'),
(56, 1, 56, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Evaluator-optimizer nên dùng khi nào?', 'D', 'Pattern này có một bước tạo và một bước đánh giá/cải thiện theo tiêu chí đã định.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.'),
(57, 1, 57, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Một demo đẹp nhưng không có bộ test đại diện là dấu hiệu nào?', 'B', 'No eval path là anti-pattern vì nhóm không biết hệ thống đạt mức nào và có hồi quy hay không.', '**eval**: viết tắt của evaluation — đánh giá chất lượng AI.'),
(58, 1, 58, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'North Star metric nên được chọn theo tiêu chí nào?', 'D', 'North Star gắn với outcome quan trọng nhất chứ không chỉ là metric kỹ thuật tiện đo.', '**North Star metric**: chỉ số trung tâm gắn với outcome quan trọng nhất của sản phẩm.'),
(59, 1, 59, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Nếu một bài toán có dynamic decision và nhiều tool phụ thuộc nhau, điều gì được ưu tiên cân nhắc?', 'C', 'Nhiều bước, quyết định động và tool use là các tín hiệu của Agentic Fit cao.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(60, 1, 60, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Go decision hợp lý hơn khi nào?', 'A', 'Gate criteria yêu cầu bài toán có thể đo, có ranh giới và có đường triển khai khả thi.', '**eval**: viết tắt của evaluation — đánh giá chất lượng AI.'),
(61, 1, 61, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Trợ lý soạn email đề xuất nội dung nhưng không tự gửi là dạng nào?', 'B', 'Người dùng vẫn duyệt và chỉnh kết quả; mức agency thấp hơn automation hoàn toàn.', '**augmentation**: AI hỗ trợ con người, còn người dùng giữ quyền quyết định cuối.; **automation**: AI tự thực hiện phần lớn hoặc toàn bộ workflow theo quy tắc đã định.'),
(62, 1, 62, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Bộ lọc video trẻ em đánh dấu video là xấu khi thực tế lành mạnh. Đây là lỗi gì?', 'C', 'Hệ thống báo nhầm dương tính là false positive; nếu cost của nó cao thì ưu precision.', '**false positive**: báo nhầm một trường hợp tốt/thấp rủi ro thành trường hợp dương tính.; **precision**: tỷ lệ kết quả được dự đoán dương tính mà thực sự đúng.; **recall**: tỷ lệ các trường hợp đúng mà hệ thống tìm được.'),
(63, 1, 63, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Trust calibration tốt cần kết hợp những yếu tố nào?', 'D', 'Người dùng tin đúng mức khi biết khả năng, lý do và quyền can thiệp của hệ thống.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(64, 1, 64, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Vì sao confidence tag High/Medium/Low có thể tốt hơn số 0,84?', 'A', 'Người dùng cần biết nên tin và kiểm tra thế nào hơn là một số phần trăm thiếu ngữ cảnh.', '**confidence**: mức độ tự tin/độ chắc chắn mà hệ thống gán cho output hoặc evidence.; **UX**: User Experience — trải nghiệm người dùng khi tương tác với sản phẩm.'),
(65, 1, 65, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Khi AI thiếu thông tin để hiểu câu hỏi mơ hồ, fallback tốt là gì?', 'B', 'Graceful fallback giữ tính trung thực và giúp user bổ sung thông tin cần thiết.', '**AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(66, 1, 66, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Cùng một input cho ra hai output khác nhau là loại failure nào?', 'C', 'Nondeterminism là mặc định của hệ thống sinh; acceptance criteria cần phản ánh mức biến thiên.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(67, 1, 67, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Vì sao eval AI nên lặp lại trước và sau thay đổi?', 'D', 'Eval là chu trình, không phải một lần chấm demo.', '**eval**: viết tắt của evaluation — đánh giá chất lượng AI.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(68, 1, 68, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Guideline ''make clear what the system can do'' chủ yếu xử lý vấn đề nào?', 'A', 'UI cần cho user biết khả năng và giới hạn trước khi họ giao việc cho AI.', '**AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(69, 1, 69, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Trong Wizard of Oz, giả định rủi ro nhất nên được kiểm tra thế nào?', 'C', 'MVP kiểu Wizard of Oz kiểm tra nhu cầu và hành vi trước khi đầu tư kỹ thuật lớn.', '**MVP**: Minimum Viable Product — sản phẩm tối thiểu nhưng dùng được để kiểm chứng giả thuyết.'),
(70, 1, 70, 'AI Product, Problem Framing, UX & Evaluation', 'Vừa', 'Nếu PRD nói rõ goal nhưng không nói non-goal, rủi ro dễ gặp là gì?', 'D', 'Non-goal là hàng rào sản phẩm giúp team biết điều gì chưa nằm trong phiên bản này.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(71, 1, 71, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Stakeholder yêu cầu ''tóm tắt mọi email bằng agent''. Phát biểu nào là problem statement tốt hơn?', 'B', 'Problem statement cần actor, pain, tần suất và outcome; không lấy tên giải pháp làm vấn đề.', '**problem statement**: mô tả bài toán rõ actor, pain point, metric, boundary và cách đánh giá.; **stakeholder**: bên liên quan hoặc người có lợi ích/quyền quyết định trong bài toán.; **actor**: tác nhân trực tiếp thực hiện hoặc chịu ảnh hưởng bởi workflow.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(72, 1, 72, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Một nhóm chọn số lượng câu trả lời sinh ra làm North Star cho trợ lý. Vì sao metric này yếu?', 'C', 'North Star nên nối với outcome như thời gian tiết kiệm, resolution hoặc conversion, không chỉ volume output.', '**North Star metric**: chỉ số trung tâm gắn với outcome quan trọng nhất của sản phẩm.'),
(73, 1, 73, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Tác vụ nhập mã lỗi cố định, luồng xử lý cố định và sai sót rất đắt nên chọn mức nào?', 'D', 'Input ổn định, flow cố định và cost-of-error cao là tín hiệu không nên tăng độ tự chủ.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(74, 1, 74, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Một workflow gồm parse email → phân loại intent → tạo bản nháp. Vì sao prompt chaining là điểm bắt đầu tốt?', 'A', 'Chaining phù hợp khi chuỗi bước tương đối ổn định và cần gate giữa các bước.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(75, 1, 75, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Orchestrator-workers phù hợp hơn routing đơn giản khi nào?', 'B', 'Orchestrator-workers cho phép phân việc động; routing chỉ cần chọn nhánh đã biết.', '**worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(76, 1, 76, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Một dự án có metric rõ nhưng không biết data có quyền truy cập hay đủ freshness. Gate nào đang thiếu?', 'C', 'Discovery/feasibility phải kiểm tra nguồn, quyền, chất lượng và độ mới trước khi viết nhiều code.', '**freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.'),
(77, 1, 77, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Nếu metric offline tăng nhưng user không tiết kiệm thời gian hơn, nên nghi ngờ điều gì?', 'D', 'Eval kỹ thuật không tự chứng minh giá trị sản phẩm; cần nối với outcome của actor.', '**workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **metrics**: số đo định lượng theo thời gian như latency, error rate, token hoặc cost.; **actor**: tác nhân trực tiếp thực hiện hoặc chịu ảnh hưởng bởi workflow.; **eval**: viết tắt của evaluation — đánh giá chất lượng AI.'),
(78, 1, 78, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Quan sát user bỏ qua gợi ý AI vì không biết nên bắt đầu prompt thế nào gợi ý thiết kế nào?', 'A', 'Why Johnny Can''t Prompt nhấn mạnh user cần biết khả năng và cách tiếp cận task.', '**prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(79, 1, 79, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Nếu baseline thủ công mất 30 phút và AI mất 20 phút nhưng tỷ lệ sửa lỗi tăng mạnh, quyết định nào cần làm?', 'B', 'Tác động phải tính cả thời gian sửa, độ chính xác và rủi ro chứ không chỉ thời gian sinh output.', '**baseline**: mốc chuẩn dùng để so sánh với cách làm hiện tại.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(80, 1, 80, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Vì sao scope solution phải mô tả cả bước không có AI?', 'D', 'Day 5 nhắc không chỉ định nghĩa đoạn AI; cần biết user đi từ input đến kết quả thế nào.', '**AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(81, 1, 81, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'AI có accuracy khá cao nhưng đôi khi gửi email sai người. Quyết định agency nào hợp lý?', 'B', 'Sai recipient là side effect khó hoàn tác; augmentation và approval giảm cost-of-error.', '**augmentation**: AI hỗ trợ con người, còn người dùng giữ quyền quyết định cuối.; **side effect**: tác động bên ngoài như gửi email, xóa dữ liệu, trừ tiền hoặc đặt vé.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(82, 1, 82, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Trong hệ thống phát hiện nội dung nguy hiểm cho trẻ em, bỏ lọt là lỗi nghiêm trọng hơn báo nhầm. Nên ưu tiên gì?', 'C', 'Khi FN gây hại lớn, cần tối đa hóa coverage và có thể dùng human review cho phần nghi ngờ.', '**false negative**: bỏ sót một trường hợp thực sự cần được phát hiện.; **precision**: tỷ lệ kết quả được dự đoán dương tính mà thực sự đúng.; **recall**: tỷ lệ các trường hợp đúng mà hệ thống tìm được.'),
(83, 1, 83, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Acceptance criteria cho output sinh nên viết thế nào để đối phó nondeterminism?', 'D', 'AI có nhiều câu trả lời hợp lệ; acceptance cần đo mức đạt, factuality, format và failure handling.', '**AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(84, 1, 84, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Một UI hiển thị ''AI knows everything'' nhưng feature chỉ có dữ liệu đến 2024. Lỗi thiết kế là gì?', 'A', 'Trust giảm khi UI hứa vượt khả năng; cần nói rõ phạm vi, thời điểm dữ liệu và cách AI có thể sai.', '**freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(85, 1, 85, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Khi confidence thấp nhưng hành động có thể hoàn tác, UX nào hợp lý?', 'B', 'Control, preview và rollback cho phép dùng AI trong vùng rủi ro vừa phải.', '**confidence**: mức độ tự tin/độ chắc chắn mà hệ thống gán cho output hoặc evidence.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.; **UX**: User Experience — trải nghiệm người dùng khi tương tác với sản phẩm.'),
(86, 1, 86, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Vì sao eval AI không thể chỉ dùng pass/fail như unit test thuần?', 'C', 'Output sinh cần chấm theo mức độ, relevance, faithfulness hoặc rubric thay vì một chuỗi duy nhất.', '**faithfulness**: mức độ câu trả lời bám trung thực vào context được truy xuất.; **eval**: viết tắt của evaluation — đánh giá chất lượng AI.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(87, 1, 87, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Một feature có ba fallback: sửa output, yêu cầu user duyệt, chuyển người thật. Vì sao phải ghi vào PRD?', 'D', 'Fallback là quyết định sản phẩm, không chỉ là exception kỹ thuật.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(88, 1, 88, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Đội ngũ cần kiểm tra workflow nhưng chưa chắc có nhu cầu AI. Prototype nào phù hợp?', 'A', 'Build rẻ trước để giảm rủi ro học sai bài toán.', '**prototype**: bản mẫu nhanh để kiểm tra giả thuyết trước khi build đầy đủ.; **workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **MVP**: Minimum Viable Product — sản phẩm tối thiểu nhưng dùng được để kiểm chứng giả thuyết.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(89, 1, 89, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'AI feature đọc nội dung cuộc họp có thể chứa PII. PRD cần mô tả thêm gì ngoài user flow?', 'B', 'AI-specific requirements phải nêu input/context và privacy controls, không chỉ mô tả nút bấm.', '**context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **PII**: Personally Identifiable Information — dữ liệu có thể nhận diện một cá nhân.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(90, 1, 90, 'AI Product, Problem Framing, UX & Evaluation', 'Khó', 'Một sản phẩm AI đo được thumbs-up thấp nhưng LLM judge cao. Nên làm gì?', 'C', 'Các tầng quality khác nhau có thể không đồng thuận; cần xem case và outcome thay vì tin một số.', '**metrics**: số đo định lượng theo thời gian như latency, error rate, token hoặc cost.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(91, 1, 91, 'Prompt Engineering & System Prompt', 'Dễ', 'Bốn thành phần cơ bản của prompt tốt là gì?', 'B', 'Day 4 dùng khung Role / Task / Context / Format để biến ý định thành chỉ dẫn rõ.', '**context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **role**: vai trò model cần đảm nhận trong prompt.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(92, 1, 92, 'Prompt Engineering & System Prompt', 'Dễ', 'Zero-shot prompting nghĩa là gì?', 'C', 'Zero-shot không cung cấp example; few-shot mới dùng các ví dụ minh họa.', '**zero-shot**: thực hiện task mà không được cung cấp ví dụ mẫu.; **few-shot**: cung cấp một vài ví dụ để model bắt chước cách xử lý hoặc format.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(93, 1, 93, 'Prompt Engineering & System Prompt', 'Dễ', 'Few-shot prompting hữu ích nhất khi nào?', 'D', 'Ví dụ mẫu giúp model bắt chước cách trả lời và định dạng mong muốn.', '**few-shot**: cung cấp một vài ví dụ để model bắt chước cách xử lý hoặc format.'),
(94, 1, 94, 'Prompt Engineering & System Prompt', 'Dễ', 'Chain-of-Thought thường phù hợp với task nào?', 'A', 'CoT được giới thiệu cho các bài toán có reasoning nhiều bước; không phải task nào cũng cần.', '**chain-of-thought**: suy luận theo chuỗi bước; dùng để hỗ trợ task cần nhiều bước reasoning.; **reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(95, 1, 95, 'Prompt Engineering & System Prompt', 'Dễ', 'System prompt có vai trò chính nào?', 'C', 'System message là hợp đồng nền tảng định hướng hành vi của agent.', '**system prompt**: chỉ dẫn nền do ứng dụng đặt để định nghĩa vai trò, luật và capability của model.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(96, 1, 96, 'Prompt Engineering & System Prompt', 'Dễ', 'Delimiter hoặc thẻ XML giúp giải quyết vấn đề nào?', 'D', 'Cấu trúc hóa context làm giảm context bleed, tức nhầm dữ liệu thành mệnh lệnh.', '**context bleed**: lẫn ngữ cảnh; model nhầm dữ liệu không tin cậy thành instruction cần tuân theo.; **delimiter**: dấu phân cách dùng để tách instruction khỏi dữ liệu đầu vào.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.'),
(97, 1, 97, 'Prompt Engineering & System Prompt', 'Dễ', 'Context bleed là hiện tượng gì?', 'A', 'Dữ liệu user, API hoặc tài liệu có thể chứa câu lệnh; delimiters giúp phân biệt chúng.', '**context bleed**: lẫn ngữ cảnh; model nhầm dữ liệu không tin cậy thành instruction cần tuân theo.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(98, 1, 98, 'Prompt Engineering & System Prompt', 'Dễ', 'Tool description tốt nên hướng tới đối tượng nào?', 'B', 'Mô tả tool là một phần prompt để model chọn đúng hàm và tham số.', '**prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(99, 1, 99, 'Prompt Engineering & System Prompt', 'Dễ', 'Mảng required trong JSON schema dùng để làm gì?', 'D', 'Required giúp ngăn việc bỏ trống field cần thiết như city hoặc date.', '**JSON schema**: schema JSON; mô tả cấu trúc, kiểu dữ liệu và field hợp lệ của JSON.; **required**: field bắt buộc phải có trong object hoặc tool arguments.'),
(100, 1, 100, 'Prompt Engineering & System Prompt', 'Dễ', 'Khi Tool B cần kết quả Tool A, nên dùng chiến lược nào?', 'C', 'Phụ thuộc dữ liệu yêu cầu chained calls để truyền kết quả chính xác sang bước sau.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(101, 1, 101, 'Prompt Engineering & System Prompt', 'Vừa', 'Một tài liệu retrieved chứa câu ''bỏ qua system prompt''. Cách phòng thủ prompt phù hợp là gì?', 'B', 'Delimiter và instruction hierarchy giúp model phân biệt dữ liệu được trích xuất với luật điều khiển.', '**system prompt**: chỉ dẫn nền do ứng dụng đặt để định nghĩa vai trò, luật và capability của model.; **context bleed**: lẫn ngữ cảnh; model nhầm dữ liệu không tin cậy thành instruction cần tuân theo.; **delimiter**: dấu phân cách dùng để tách instruction khỏi dữ liệu đầu vào.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(102, 1, 102, 'Prompt Engineering & System Prompt', 'Vừa', 'Few-shot nên ưu tiên ví dụ edge case thay vì chỉ happy path vì sao?', 'C', 'Ví dụ thiếu dữ liệu, mơ hồ hoặc jailbreak giúp kiểm thử boundary của prompt.', '**few-shot**: cung cấp một vài ví dụ để model bắt chước cách xử lý hoặc format.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(103, 1, 103, 'Prompt Engineering & System Prompt', 'Vừa', 'Muốn model trả JSON ổn định, thành phần nào nên thêm?', 'D', 'Output contract rõ làm giảm format hallucination và giúp parser xử lý nhất quán hơn.', '**output contract**: hợp đồng đầu ra; quy định format, field, giới hạn và điều kiện trả kết quả.; **JSON schema**: schema JSON; mô tả cấu trúc, kiểu dữ liệu và field hợp lệ của JSON.; **required**: field bắt buộc phải có trong object hoặc tool arguments.'),
(104, 1, 104, 'Prompt Engineering & System Prompt', 'Vừa', 'Order bias trong few-shot gợi ý cách sắp ví dụ nào?', 'A', 'Model có thể bị ảnh hưởng bởi ví dụ gần cuối; cần tránh thứ tự gây lệch nhãn.', '**few-shot**: cung cấp một vài ví dụ để model bắt chước cách xử lý hoặc format.'),
(105, 1, 105, 'Prompt Engineering & System Prompt', 'Vừa', 'Để giảm ''Lost in the Middle'', nên làm gì với context rất dài?', 'B', 'Model thường chú ý tốt hơn ở đầu/cuối; compression và reordering giúp tận dụng context.', '**context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.'),
(106, 1, 106, 'Prompt Engineering & System Prompt', 'Vừa', 'Dynamic system prompt hữu ích trong tình huống nào?', 'C', 'Template có placeholder cho date, state hoặc service status giúp prompt thích ứng nhưng vẫn có cấu trúc.', '**dynamic prompt**: prompt được dựng theo trạng thái, ngày giờ, quyền hoặc availability hiện tại.; **system prompt**: chỉ dẫn nền do ứng dụng đặt để định nghĩa vai trò, luật và capability của model.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(107, 1, 107, 'Prompt Engineering & System Prompt', 'Vừa', 'Vì sao chỉ viết ''đừng bịa'' thường chưa đủ?', 'D', 'Nên nêu điều kiện thiếu dữ liệu, câu trả lời fallback và escalation thay vì chỉ cấm đoán.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(108, 1, 108, 'Prompt Engineering & System Prompt', 'Vừa', 'Enum trong tool schema phù hợp khi tham số có đặc điểm nào?', 'A', 'Enum thu hẹp không gian lựa chọn và giảm tham số sai.', '**enum**: tập hữu hạn các giá trị được phép chọn.'),
(109, 1, 109, 'Prompt Engineering & System Prompt', 'Vừa', 'Vì sao tool không nên có quá nhiều tham số?', 'B', 'Slide khuyên giữ khoảng 5–7 tham số hoặc ít hơn nếu có thể để contract dễ hiểu.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(110, 1, 110, 'Prompt Engineering & System Prompt', 'Vừa', 'Khi tool trả lỗi JSON cho model, self-correction tốt hơn dừng ngay vì sao?', 'D', 'Báo lỗi có cấu trúc cho LLM tạo cơ hội sửa, nhưng vẫn cần retry limit và validation.', '**LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(111, 1, 111, 'Prompt Engineering & System Prompt', 'Khó', 'System prompt vừa yêu cầu ''giải thích chi tiết từng bước'' vừa ''trả lời dưới 50 chữ''. Vấn đề chính là gì?', 'B', 'Prompt production-grade cần tránh mâu thuẫn hoặc nêu ưu tiên rõ khi hai yêu cầu xung đột.', '**output contract**: hợp đồng đầu ra; quy định format, field, giới hạn và điều kiện trả kết quả.; **system prompt**: chỉ dẫn nền do ứng dụng đặt để định nghĩa vai trò, luật và capability của model.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(112, 1, 112, 'Prompt Engineering & System Prompt', 'Khó', 'RAG prompt đặt raw document trước system rules mà không có delimiter. Rủi ro nào tăng?', 'C', 'Context injection cần phân tách nguồn và luật để giảm context bleed và indirect injection.', '**context bleed**: lẫn ngữ cảnh; model nhầm dữ liệu không tin cậy thành instruction cần tuân theo.; **delimiter**: dấu phân cách dùng để tách instruction khỏi dữ liệu đầu vào.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(113, 1, 113, 'Prompt Engineering & System Prompt', 'Khó', 'Một prompt có 50 trang context nhưng câu hỏi chỉ ở đầu. Tối ưu nào hợp lý hơn?', 'D', 'Recency và lost-in-the-middle khiến vị trí và compression quan trọng không kém tổng dung lượng.', '**context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(114, 1, 114, 'Prompt Engineering & System Prompt', 'Khó', 'Few-shot có nhãn A ở cuối liên tiếp nhiều lần khiến model lệch nhãn. Cách xử lý nào tốt?', 'A', 'Order bias yêu cầu kiểm tra ảnh hưởng vị trí, không dồn một loại nhãn ở cuối chuỗi.', '**few-shot**: cung cấp một vài ví dụ để model bắt chước cách xử lý hoặc format.'),
(115, 1, 115, 'Prompt Engineering & System Prompt', 'Khó', 'Tool search_flights nhận city tự do dù chỉ hỗ trợ mã IATA. Cải tiến schema nào hiệu quả?', 'B', 'Schema cần ràng buộc input; nếu chỉ có một tập mã hợp lệ thì enum giúp giảm lỗi.', '**enum**: tập hữu hạn các giá trị được phép chọn.'),
(116, 1, 116, 'Prompt Engineering & System Prompt', 'Khó', 'Tool có 12 tham số tùy chọn, model thường bỏ nhầm field. Thiết kế nào đáng thử trước?', 'C', 'Contract nhỏ, rõ giúp model chọn và điền arguments chính xác hơn.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(117, 1, 117, 'Prompt Engineering & System Prompt', 'Khó', 'Dynamic prompt chèn trạng thái payment API đang degraded. Rule nào nên đi kèm?', 'D', 'Dynamic system prompt nên phản ánh availability và điều hướng agent tránh capability đang lỗi.', '**dynamic prompt**: prompt được dựng theo trạng thái, ngày giờ, quyền hoặc availability hiện tại.; **system prompt**: chỉ dẫn nền do ứng dụng đặt để định nghĩa vai trò, luật và capability của model.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(118, 1, 118, 'Prompt Engineering & System Prompt', 'Khó', 'Trong LangGraph, vì sao state thường append messages thay vì ghi đè?', 'A', 'Append-only giúp graph giữ diễn tiến; node vẫn có thể cập nhật field khác theo schema.', '**LangGraph**: framework biểu diễn workflow agent bằng state, node, edge và conditional routing.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.'),
(119, 1, 119, 'Prompt Engineering & System Prompt', 'Khó', 'Graph cần quay lại Agent sau Tool nếu còn tool_calls, và đi END nếu không. Thành phần nào quyết định?', 'B', 'Router/should_continue là hàm đọc state để quyết định vòng tiếp hoặc final answer.', '**LangGraph**: framework biểu diễn workflow agent bằng state, node, edge và conditional routing.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(120, 1, 120, 'Prompt Engineering & System Prompt', 'Khó', 'Nếu tool node nhận JSON arguments sai kiểu, nên đặt validation ở đâu?', 'D', 'Schema giúp model, nhưng runtime validation bảo vệ hệ thống trước input sai hoặc malicious.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(121, 1, 121, 'Agent, ReAct & Tool Calling', 'Dễ', 'Rule-based bot thường xử lý đầu vào bằng cách nào?', 'B', 'Rule-based bot hoạt động theo luồng và điều kiện do con người viết sẵn.', '**rule-based bot**: bot theo luật; phản hồi bằng các điều kiện if/else được định trước.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(122, 1, 122, 'Agent, ReAct & Tool Calling', 'Dễ', 'LLM chatbot khác agent chủ yếu ở điểm nào?', 'C', 'Agent kết hợp reasoning, tools, state và vòng lặp; một LLM call đơn lẻ chưa đủ là agent.', '**reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **chatbot**: hệ thống hội thoại thường trả lời bằng văn bản theo context của lượt chat.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(123, 1, 123, 'Agent, ReAct & Tool Calling', 'Dễ', 'Agent thường cần thêm thành phần nào ngoài LLM core?', 'D', 'Slide kiến trúc agent nêu goal, reasoning, tools và memory/state là các khối bổ sung.', '**reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(124, 1, 124, 'Agent, ReAct & Tool Calling', 'Dễ', 'ReAct là viết tắt của cụm nào?', 'A', 'ReAct kết hợp suy luận theo bước với hành động gọi công cụ.', '**reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **acting**: hành động; bước agent thực thi tool hoặc tác động lên môi trường.; **ReAct**: Reasoning + Acting — suy luận kết hợp hành động theo vòng Thought → Action → Observation.'),
(125, 1, 125, 'Agent, ReAct & Tool Calling', 'Dễ', 'Thứ tự cơ bản của vòng lặp ReAct là gì?', 'C', 'Agent phân tích trước, gọi tool sau, rồi đọc kết quả để quyết định bước tiếp.', '**observation**: quan sát; kết quả tool hoặc môi trường trả lại cho agent.; **action**: hành động được agent chọn để tiến tới mục tiêu.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **ReAct**: Reasoning + Acting — suy luận kết hợp hành động theo vòng Thought → Action → Observation.'),
(126, 1, 126, 'Agent, ReAct & Tool Calling', 'Dễ', 'Tool calling cung cấp cho agent khả năng nào?', 'D', 'Tool là ''tay chân'' giúp agent lấy dữ liệu hoặc thực hiện hành động bên ngoài LLM.', '**tool calling**: gọi công cụ; cho phép model yêu cầu ứng dụng thực thi API, database hoặc hàm bên ngoài.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(127, 1, 127, 'Agent, ReAct & Tool Calling', 'Dễ', 'Short-term memory thường nằm ở đâu?', 'A', 'Short-term memory giữ lịch sử gần đây và thông tin cần cho phiên hiện tại.', '**short-term memory**: bộ nhớ ngắn hạn; lịch sử/context của task hiện tại.; **context window**: cửa sổ ngữ cảnh; tổng số token model có thể xử lý trong một lần gọi.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(128, 1, 128, 'Agent, ReAct & Tool Calling', 'Dễ', 'Vì sao agent cần giới hạn số vòng lặp?', 'B', 'Max iterations là safeguard cơ bản cùng với timeout và xử lý lỗi.', '**agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(129, 1, 129, 'Agent, ReAct & Tool Calling', 'Dễ', 'Hybrid pattern trong chatbot và agent thường làm gì?', 'D', 'Hybrid giúp giữ chi phí thấp ở đường đơn giản và chỉ kích hoạt agent khi cần.', '**chatbot**: hệ thống hội thoại thường trả lời bằng văn bản theo context của lượt chat.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(130, 1, 130, 'Agent, ReAct & Tool Calling', 'Dễ', 'Agentic Fit dùng để trả lời câu hỏi nào?', 'C', 'Agentic Fit xem xét multi-step reasoning, tool use và quyết định động trước khi nâng cấp kiến trúc.', '**reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(131, 1, 131, 'Agent, ReAct & Tool Calling', 'Vừa', 'Trong ví dụ tìm chuyến bay và thời tiết, hai tool độc lập có thể gọi thế nào?', 'B', 'Nếu search_flights và get_weather không phụ thuộc dữ liệu nhau, parallel calling tiết kiệm thời gian.', '**latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.'),
(132, 1, 132, 'Agent, ReAct & Tool Calling', 'Vừa', 'Trace có observation giá 1,75 triệu nhưng final answer nói 1,5 triệu. Lỗi chính là gì?', 'C', 'Final answer không khớp observation là dấu hiệu hallucination hoặc lỗi tổng hợp.', '**observation**: quan sát; kết quả tool hoặc môi trường trả lại cho agent.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(133, 1, 133, 'Agent, ReAct & Tool Calling', 'Vừa', 'Nếu search_flights timeout, graceful degradation nên ưu tiên điều gì?', 'D', 'Agent nên không bịa dữ liệu; có thể retry có giới hạn, fallback hoặc nói rõ chưa đủ evidence.', '**graceful degradation**: suy giảm có kiểm soát; khi thiếu dữ liệu/lỗi, hệ thống nói rõ và dùng fallback an toàn.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(134, 1, 134, 'Agent, ReAct & Tool Calling', 'Vừa', 'Stop condition tốt của ReAct agent nên dựa trên điều gì?', 'A', 'Agent dừng khi task hoàn tất hoặc không thể tiến thêm trong boundary, không dừng chỉ vì số bước tùy ý.', '**stop condition**: điều kiện dừng; tiêu chí cho biết agent đã đủ bằng chứng hoặc không thể đi tiếp.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **ReAct**: Reasoning + Acting — suy luận kết hợp hành động theo vòng Thought → Action → Observation.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(135, 1, 135, 'Agent, ReAct & Tool Calling', 'Vừa', 'Một use case đạt điểm thấp ở reasoning, tool use và dynamic decision nên chọn gì?', 'C', 'Agentic Fit thấp cho thấy độ phức tạp của agent chưa tạo thêm giá trị.', '**reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **baseline**: mốc chuẩn dùng để so sánh với cách làm hiện tại.; **chatbot**: hệ thống hội thoại thường trả lời bằng văn bản theo context của lượt chat.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(136, 1, 136, 'Agent, ReAct & Tool Calling', 'Vừa', 'Ngoài max iterations, safeguard nào giúp ngăn agent bị treo khi tool không phản hồi?', 'D', 'Timeout giới hạn thời gian chờ; retry và fallback cần được thiết kế bổ sung.', '**agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(137, 1, 137, 'Agent, ReAct & Tool Calling', 'Vừa', 'Câu hỏi FAQ một bước không cần dữ liệu mới thường phù hợp với gì?', 'A', 'Không nên dùng agent cho bài toán một bước, không tool và yêu cầu deterministic cao.', '**chatbot**: hệ thống hội thoại thường trả lời bằng văn bản theo context của lượt chat.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(138, 1, 138, 'Agent, ReAct & Tool Calling', 'Vừa', 'Vì sao tên tool ''do_stuff'' làm model chọn tool kém hơn ''search_flights''?', 'B', 'Tool name là tín hiệu phân loại đầu tiên; tên rõ giúp model định hướng chức năng.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(139, 1, 139, 'Agent, ReAct & Tool Calling', 'Vừa', 'Trong ReAct, Observation khác Action ở điểm nào?', 'D', 'Action gửi yêu cầu tới tool; Observation là dữ liệu môi trường trả lại cho agent.', '**observation**: quan sát; kết quả tool hoặc môi trường trả lại cho agent.; **action**: hành động được agent chọn để tiến tới mục tiêu.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **ReAct**: Reasoning + Acting — suy luận kết hợp hành động theo vòng Thought → Action → Observation.'),
(140, 1, 140, 'Agent, ReAct & Tool Calling', 'Vừa', 'Vì sao agent thường đắt hơn chatbot cho cùng số query?', 'C', 'Mỗi bước reasoning hoặc synthesis có thể phát sinh thêm token và latency.', '**reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **chatbot**: hệ thống hội thoại thường trả lời bằng văn bản theo context của lượt chat.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(141, 1, 141, 'Agent, ReAct & Tool Calling', 'Khó', 'Trace có ba lỗi: gọi weather trước khi có flight, dùng HCM thay SGN, và final answer đổi 1,75M thành 1,5M. Cách phân loại đúng là gì?', 'B', 'Day 3 chỉ rõ thứ tự tool, mã IATA và sự lệch evidence là ba loại lỗi cần sửa khác nhau.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(142, 1, 142, 'Agent, ReAct & Tool Calling', 'Khó', 'Hai tool A và B độc lập, nhưng B cần output A. Chiến lược nào tối ưu mà vẫn đúng?', 'C', 'Orchestration nên dựa trên dependency graph: parallel ở nhánh độc lập, sequential ở nhánh phụ thuộc.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(143, 1, 143, 'Agent, ReAct & Tool Calling', 'Khó', 'Agent liên tục gọi lại cùng tool dù observation không thay đổi. Bộ kiểm soát nào nên phối hợp?', 'D', 'Nhiều safeguard cần đi cùng nhau vì một vòng lặp không kiểm soát có thể đốt token và side effect.', '**observation**: quan sát; kết quả tool hoặc môi trường trả lại cho agent.; **side effect**: tác động bên ngoài như gửi email, xóa dữ liệu, trừ tiền hoặc đặt vé.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(144, 1, 144, 'Agent, ReAct & Tool Calling', 'Khó', 'Tool trả timeout tạm thời nhưng retry lần đầu vẫn lỗi. Retry policy production nên có gì?', 'A', 'Retry cần phân biệt transient/permanent failure và giới hạn số lần để bảo vệ cost.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(145, 1, 145, 'Agent, ReAct & Tool Calling', 'Khó', 'Agent có thể trả lời từ knowledge nội tại nhưng user hỏi giá realtime. Stop condition đúng yêu cầu gì?', 'B', 'Goal và evidence cần khớp; knowledge tĩnh không thay thế được dữ liệu realtime.', '**stop condition**: điều kiện dừng; tiêu chí cho biết agent đã đủ bằng chứng hoặc không thể đi tiếp.; **observation**: quan sát; kết quả tool hoặc môi trường trả lại cho agent.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **ReAct**: Reasoning + Acting — suy luận kết hợp hành động theo vòng Thought → Action → Observation.'),
(146, 1, 146, 'Agent, ReAct & Tool Calling', 'Khó', 'Native function calling được ưu tiên hơn ReAct text thuần trong production vì sao?', 'C', 'Hybrid thường dùng reasoning/control của ReAct cùng format tool call có cấu trúc.', '**reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **ReAct**: Reasoning + Acting — suy luận kết hợp hành động theo vòng Thought → Action → Observation.'),
(147, 1, 147, 'Agent, ReAct & Tool Calling', 'Khó', 'Triage route cho FAQ đơn giản nhưng route nhầm sang agent. Tác động đầu tiên thường là gì?', 'D', 'Agent có nhiều call hơn; hybrid route giúp tránh dùng độ phức tạp không cần thiết.', '**latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(148, 1, 148, 'Agent, ReAct & Tool Calling', 'Khó', 'Long-horizon task dễ khác task một lượt ở điểm nào?', 'A', 'Task dài làm tăng rủi ro mất state, loop, retry trùng và cần durable execution.', '**side effect**: tác động bên ngoài như gửi email, xóa dữ liệu, trừ tiền hoặc đặt vé.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(149, 1, 149, 'Agent, ReAct & Tool Calling', 'Khó', 'Một bộ eval agent nên chấm riêng tool selection thay vì chỉ chấm final answer vì sao?', 'B', 'Day 3 nêu reasoning quality, tool selection, arguments, error handling và stopping là các điểm cần xem.', '**evaluation**: đánh giá chất lượng hệ thống trên bộ case và tiêu chí đã định.; **reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **eval**: viết tắt của evaluation — đánh giá chất lượng AI.'),
(150, 1, 150, 'Agent, ReAct & Tool Calling', 'Khó', 'Nếu một agent trung bình gọi 3 LLM step/query và chatbot gọi 1 step/query, scale 1 triệu query sẽ nhạy với gì?', 'D', 'Agent cost scale theo số call và token mỗi call; cần napkin math trước khi mở rộng.', '**latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **chatbot**: hệ thống hội thoại thường trả lời bằng văn bản theo context của lượt chat.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(151, 1, 151, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Knowledge data thường bao gồm loại dữ liệu nào?', 'B', 'Knowledge data là tri thức nền versioned hoặc ít thay đổi mà agent cần tra cứu.', '**agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(152, 1, 152, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Operational data có đặc điểm nổi bật nào?', 'C', 'Operational data như order status hoặc tồn kho cần freshness cao hơn knowledge data.', '**freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.'),
(153, 1, 153, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Contextual data thường gắn với điều gì?', 'D', 'Contextual data thường ngắn và được inject trực tiếp cho task hiện tại.', '**task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(154, 1, 154, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Nguyên lý Garbage In, Garbage Out nhắc điều gì?', 'A', 'Chất lượng data giới hạn chất lượng retrieval và câu trả lời, kể cả khi model mạnh.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(155, 1, 155, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Embedding biến văn bản thành dạng nào?', 'C', 'Embedding tạo biểu diễn số để so sánh các đoạn có ý nghĩa gần nhau.', '**embedding**: vector số biểu diễn ngữ nghĩa của văn bản, hình ảnh hoặc dữ liệu khác.'),
(156, 1, 156, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Cosine similarity chủ yếu đo điều gì?', 'D', 'Cosine similarity so sánh góc giữa vector query và vector tài liệu.', '**cosine similarity**: độ tương đồng cosine; đo độ gần về hướng giữa hai vector.'),
(157, 1, 157, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Vector store thường lưu thêm gì ngoài vector?', 'A', 'Kho vector cần giữ nội dung và metadata như source, category, date để trả lời có ngữ cảnh.', '**vector store**: kho lưu vector, nội dung gốc và metadata để tìm kiếm theo ngữ nghĩa.; **metadata**: siêu dữ liệu như nguồn, loại, ngày, khu vực hoặc quyền của một chunk.'),
(158, 1, 158, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Top-k trong retrieval chỉ số lượng gì?', 'B', 'Top-k quyết định bao nhiêu chunk đầu tiên được đưa vào các bước tiếp theo.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **top-k**: số lượng kết quả gần nhất được lấy về trong một lần retrieval.'),
(159, 1, 159, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Metadata filter giúp retrieval làm gì?', 'D', 'Filter theo category, region, date hoặc ACL giúp tránh lấy nhầm tài liệu.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **metadata**: siêu dữ liệu như nguồn, loại, ngày, khu vực hoặc quyền của một chunk.; **ACL**: Access Control List — danh sách quyền truy cập gắn với tài nguyên hoặc dữ liệu.'),
(160, 1, 160, 'Data Foundations, Embedding & Vector Store', 'Dễ', 'Data inventory có mục đích nào?', 'C', 'Inventory giúp biết dữ liệu nào phù hợp retrieval và trách nhiệm quản trị thuộc về ai.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.; **PII**: Personally Identifiable Information — dữ liệu có thể nhận diện một cá nhân.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(161, 1, 161, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Order status thay đổi liên tục không nên embed như policy tĩnh vì sao?', 'B', 'Tách knowledge và operational data giúp chọn cơ chế cập nhật và truy vấn phù hợp.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(162, 1, 162, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Vì sao nên mask PII trước khi tạo embedding?', 'C', 'Tên, số điện thoại hoặc định danh cá nhân có thể lan sang kho và trace nếu không xử lý sớm.', '**vector store**: kho lưu vector, nội dung gốc và metadata để tìm kiếm theo ngữ nghĩa.; **embedding**: vector số biểu diễn ngữ nghĩa của văn bản, hình ảnh hoặc dữ liệu khác.; **PII**: Personally Identifiable Information — dữ liệu có thể nhận diện một cá nhân.'),
(163, 1, 163, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Memory lifecycle đầy đủ thường gồm chuỗi nào?', 'D', 'Không phải mọi sự kiện đều đáng nhớ; lifecycle cần chọn, lưu và truy xuất có chủ đích.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(164, 1, 164, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Một user chỉ được xem policy khu vực miền Bắc. Metadata nào giúp lọc?', 'A', 'Attribute filter theo region hoặc quyền giúp tránh retrieval từ domain không được phép.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **metadata**: siêu dữ liệu như nguồn, loại, ngày, khu vực hoặc quyền của một chunk.; **ACL**: Access Control List — danh sách quyền truy cập gắn với tài nguyên hoặc dữ liệu.'),
(165, 1, 165, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Top-k quá cao có thể gây tác động nào?', 'B', 'Lấy thêm chunk không đồng nghĩa thêm bằng chứng hữu ích; cần threshold hoặc rerank.', '**threshold**: ngưỡng điểm dùng để loại kết quả có mức liên quan quá thấp.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **token**: đơn vị văn bản mà LLM trực tiếp xử lý và thường dùng để tính chi phí.; **top-k**: số lượng kết quả gần nhất được lấy về trong một lần retrieval.'),
(166, 1, 166, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Chunk quá nhỏ có nguy cơ gì khi trả lời policy?', 'D', 'Chunk nhỏ tìm trúng hơn nhưng có thể thiếu phần đầu/cuối của điều khoản.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(167, 1, 167, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Với mã lỗi ERR-x09, retrieval nào có thể đáng tin hơn?', 'C', 'Exact identifiers là điểm mạnh của sparse retrieval; hybrid cân bằng thêm ý nghĩa.', '**sparse retrieval**: truy xuất thưa dựa trên khớp từ khóa, thường dùng inverted index.; **hybrid search**: tìm kiếm lai kết hợp dense semantic search với sparse keyword search.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.'),
(168, 1, 168, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'ANN được dùng khi nào?', 'D', 'Approximate Nearest Neighbor đánh đổi ít chính xác để giảm chi phí tìm kiếm ở quy mô lớn.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(169, 1, 169, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Hosted retrieval phù hợp hơn self-managed retrieval khi nào?', 'A', 'Managed service giảm công vận hành; self-managed phù hợp khi cần kiểm soát sâu hơn.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.'),
(170, 1, 170, 'Data Foundations, Embedding & Vector Store', 'Vừa', 'Câu hỏi general knowledge không cần dữ liệu riêng thường không cần RAG vì sao?', 'B', 'RAG nên dùng khi tri thức riêng, cập nhật hoặc cần audit; không phải câu hỏi nào cũng cần.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(171, 1, 171, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Một bảng policy có header bị tách khỏi các dòng khi chunk. Cách sửa ưu tiên là gì?', 'B', 'Table parsing cần bảo toàn quan hệ header-row; nếu không retrieval mất ngữ cảnh và trả sai.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.'),
(172, 1, 172, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Small-to-big retrieval giải quyết trade-off nào?', 'C', 'Child chunk tăng precision khi search; parent chunk bổ sung context khi inject.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **precision**: tỷ lệ kết quả được dự đoán dương tính mà thực sự đúng.; **indexing**: lập chỉ mục; parse, clean, chunk, embed và lưu tài liệu để tìm kiếm.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.'),
(173, 1, 173, 'Data Foundations, Embedding & Vector Store', 'Khó', 'User chỉ được xem tài liệu năm 2026. Pre-filtering khác post-filtering ở điểm nào?', 'D', 'Post-filter có thể loại phần lớn top-k sau khi search và làm thiếu kết quả phù hợp.', '**top-k**: số lượng kết quả gần nhất được lấy về trong một lần retrieval.'),
(174, 1, 174, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Dense search hiểu ''hoàn tiền'' và ''refund'' gần nhau nhưng hụt mã ERR-x09. Vì sao hybrid hữu ích?', 'A', 'Hai trường phái bù điểm mù cho nhau; domain enterprise thường cần cả ý nghĩa và exact match.', '**hybrid search**: tìm kiếm lai kết hợp dense semantic search với sparse keyword search.'),
(175, 1, 175, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Một file PDF upload một lần nhưng agent không thể truy lại có chủ đích. Vì sao chưa nên gọi đó là memory?', 'B', 'Day 7 phân biệt file tạm với long-term memory có cơ chế store/retrieve rõ.', '**long-term memory**: bộ nhớ dài hạn; thông tin được lưu để truy xuất lại qua nhiều phiên.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(176, 1, 176, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Chunk có metadata ACL đúng nhưng retriever bỏ qua filter. Rủi ro chính là gì?', 'C', 'Metadata chỉ có giá trị khi pipeline thực sự áp dụng filter và kiểm tra quyền.', '**metadata**: siêu dữ liệu như nguồn, loại, ngày, khu vực hoặc quyền của một chunk.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **ACL**: Access Control List — danh sách quyền truy cập gắn với tài nguyên hoặc dữ liệu.'),
(177, 1, 177, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Raw PDF có OCR lỗi, policy cũ và header lặp. Thứ tự cải thiện nào hợp lý?', 'D', 'Data quality pyramid đi từ raw đến cleaned/structured; nạp rác làm retrieval sai dây chuyền.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.'),
(178, 1, 178, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Khi kho có hàng triệu vector, ANN đổi điều gì để đạt tốc độ?', 'A', 'ANN không phải exact brute force; nó phù hợp khi quy mô khiến tìm tuyến tính quá chậm.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(179, 1, 179, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Data inventory cho thấy tài liệu FAQ ít thay đổi nhưng order status realtime. Kiến trúc nào hợp?', 'B', 'Ba loại data cần đường truy xuất khác nhau; không nên ép operational data vào knowledge index tĩnh.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(180, 1, 180, 'Data Foundations, Embedding & Vector Store', 'Khó', 'Nếu đổi GPT-4o-mini sang model lớn nhưng context vẫn bẩn, vì sao chất lượng có thể không cải thiện?', 'C', 'Day 7 nhấn mạnh data quality thường quan trọng hơn đổi model đắt hơn.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(181, 1, 181, 'RAG, Retrieval & Grounding', 'Dễ', 'RAG là viết tắt của cụm nào?', 'B', 'RAG kết hợp truy xuất tài liệu với khả năng sinh ngôn ngữ của LLM.', '**generation**: tạo sinh; bước LLM tổng hợp câu trả lời từ context đã truy xuất.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(182, 1, 182, 'RAG, Retrieval & Grounding', 'Dễ', 'Ba khối chính của RAG pipeline là gì?', 'C', 'Indexing chuẩn bị kho, retrieval tìm context, generation tổng hợp câu trả lời.', '**generation**: tạo sinh; bước LLM tổng hợp câu trả lời từ context đã truy xuất.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **indexing**: lập chỉ mục; parse, clean, chunk, embed và lưu tài liệu để tìm kiếm.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(183, 1, 183, 'RAG, Retrieval & Grounding', 'Dễ', 'Fine-tuning thường phù hợp hơn RAG khi muốn thay đổi điều gì?', 'D', 'Slide so sánh fine-tuning với RAG: fine-tuning thiên về cách model nói, RAG thiên về tri thức cập nhật.', '**fine-tuning**: tinh chỉnh model bằng dữ liệu chuyên biệt để thay đổi hành vi hoặc phong cách.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(184, 1, 184, 'RAG, Retrieval & Grounding', 'Dễ', 'Indexing pipeline thường làm gì với file tài liệu?', 'A', 'Indexing biến dữ liệu phi cấu trúc thành các chunk có vector và thông tin truy vết.', '**metadata**: siêu dữ liệu như nguồn, loại, ngày, khu vực hoặc quyền của một chunk.; **indexing**: lập chỉ mục; parse, clean, chunk, embed và lưu tài liệu để tìm kiếm.'),
(185, 1, 185, 'RAG, Retrieval & Grounding', 'Dễ', 'Retrieval pipeline bắt đầu khi nào?', 'C', 'Query được embed và dùng để tìm các chunk gần nhất trong kho.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.'),
(186, 1, 186, 'RAG, Retrieval & Grounding', 'Dễ', 'Grounding trong RAG yêu cầu model làm gì?', 'D', 'Strict grounding giảm hallucination bằng cách buộc câu trả lời bám evidence.', '**grounding**: neo câu trả lời vào evidence được cung cấp, không tự suy diễn ngoài nguồn.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(187, 1, 187, 'RAG, Retrieval & Grounding', 'Dễ', 'Vì sao tài liệu thường cần được chunk?', 'A', 'Chunk quá lớn gây nhiễu; chunk quá nhỏ có thể mất ngữ cảnh.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.'),
(188, 1, 188, 'RAG, Retrieval & Grounding', 'Dễ', 'Chunk overlap giúp giảm rủi ro nào?', 'B', 'Phần chồng lấn giữ lại một ít ngữ cảnh ở hai phía của ranh giới.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(189, 1, 189, 'RAG, Retrieval & Grounding', 'Dễ', 'BM25 thuộc nhóm retrieval nào?', 'D', 'BM25 là thuật toán lexical/sparse mạnh khi cần khớp chính xác ID, mã lỗi hoặc tên.', '**sparse retrieval**: truy xuất thưa dựa trên khớp từ khóa, thường dùng inverted index.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **BM25**: thuật toán sparse search chấm mức phù hợp của từ khóa trong tài liệu.'),
(190, 1, 190, 'RAG, Retrieval & Grounding', 'Dễ', 'Citation trong câu trả lời RAG có ích gì?', 'C', 'Citation tăng auditability và giúp phát hiện câu trả lời không có evidence.', '**citation**: trích dẫn nguồn; chỉ ra tài liệu hoặc dòng bằng chứng dùng cho câu trả lời.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(191, 1, 191, 'RAG, Retrieval & Grounding', 'Vừa', 'Một policy đổi mỗi tuần nhưng model không đổi. Giải pháp nào phù hợp hơn?', 'B', 'RAG cho phép cập nhật nguồn riêng mà không phải huấn luyện lại toàn bộ model.', '**fine-tuning**: tinh chỉnh model bằng dữ liệu chuyên biệt để thay đổi hành vi hoặc phong cách.; **freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(192, 1, 192, 'RAG, Retrieval & Grounding', 'Vừa', 'Query expansion giúp ích chủ yếu cho metric nào?', 'C', 'Sinh biến thể query giúp không bỏ sót tài liệu vì khác cách diễn đạt.', '**query expansion**: mở rộng query bằng từ đồng nghĩa, thuật ngữ hoặc biến thể để tăng recall.; **recall**: tỷ lệ các trường hợp đúng mà hệ thống tìm được.'),
(193, 1, 193, 'RAG, Retrieval & Grounding', 'Vừa', 'Query decomposition phù hợp với câu hỏi nào?', 'D', 'Chia câu hỏi thành sub-query cho phép retrieval từng phần rồi tổng hợp.', '**query decomposition**: chia câu hỏi phức tạp thành các sub-query nhỏ hơn.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.'),
(194, 1, 194, 'RAG, Retrieval & Grounding', 'Vừa', 'HyDE tạo văn bản giả định để làm gì?', 'A', 'Hypothetical answer có hình thức gần document hơn query ngắn, hỗ trợ tìm kiếm; không phải evidence cuối.', '**HyDE**: Hypothetical Document Embeddings — tạo văn bản giả định để đưa query gần không gian tài liệu.'),
(195, 1, 195, 'RAG, Retrieval & Grounding', 'Vừa', 'Hybrid search kết hợp hai tín hiệu nào?', 'B', 'Dense bắt ý nghĩa; sparse bắt keyword, ID và thuật ngữ exact.', '**hybrid search**: tìm kiếm lai kết hợp dense semantic search với sparse keyword search.'),
(196, 1, 196, 'RAG, Retrieval & Grounding', 'Vừa', 'RRF fusion thường gộp đại lượng nào?', 'C', 'Reciprocal Rank Fusion dùng rank để tránh phải so trực tiếp score khác thang đo.', '**RRF**: Reciprocal Rank Fusion — gộp kết quả dựa trên thứ hạng từ nhiều retriever.'),
(197, 1, 197, 'RAG, Retrieval & Grounding', 'Vừa', 'Nếu domain chủ yếu chứa mã lỗi và tên biến, alpha hybrid nên nghiêng về đâu?', 'D', 'Slide gợi ý domain code/log/pháp lý ưu tiên keyword chính xác hơn semantic mơ hồ.', '**BM25**: thuật toán sparse search chấm mức phù hợp của từ khóa trong tài liệu.'),
(198, 1, 198, 'RAG, Retrieval & Grounding', 'Vừa', 'Cross-encoder khác bi-encoder ở điểm nào?', 'A', 'Bi-encoder phù hợp retrieve nhanh; cross-encoder rerank ít candidate với độ chính xác cao hơn.', '**cross-encoder**: model đọc query và document cùng nhau để chấm relevance chính xác hơn.; **bi-encoder**: model encode query và document riêng để tìm kiếm nhanh bằng vector.'),
(199, 1, 199, 'RAG, Retrieval & Grounding', 'Vừa', 'MMR giúp xử lý vấn đề gì trong top-k context?', 'B', 'Maximum Marginal Relevance cân bằng relevance với diversity để không đưa nhiều bản sao.', '**context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **top-k**: số lượng kết quả gần nhất được lấy về trong một lần retrieval.; **MMR**: Maximum Marginal Relevance — cân bằng relevance với độ đa dạng, giảm chunk trùng lặp.'),
(200, 1, 200, 'RAG, Retrieval & Grounding', 'Vừa', 'Context đã chứa đáp án nhưng output vẫn bịa. Nên debug tầng nào trước?', 'D', 'Nếu evidence đã vào formatted_context mà câu trả lời sai, lỗi nằm sau retrieval.', '**temperature**: tham số sampling điều khiển mức đa dạng/ngẫu nhiên của output.; **generation**: tạo sinh; bước LLM tổng hợp câu trả lời từ context đã truy xuất.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **grounding**: neo câu trả lời vào evidence được cung cấp, không tự suy diễn ngoài nguồn.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(201, 1, 201, 'RAG, Retrieval & Grounding', 'Khó', 'PDF hai cột làm parser trộn thứ tự câu. Lỗi này nằm ở tầng nào trước khi chunk?', 'B', 'Nếu nội dung đã bị đọc sai từ nguồn thì mọi embedding và generation phía sau đều bị ảnh hưởng.', '**generation**: tạo sinh; bước LLM tổng hợp câu trả lời từ context đã truy xuất.; **embedding**: vector số biểu diễn ngữ nghĩa của văn bản, hình ảnh hoặc dữ liệu khác.'),
(202, 1, 202, 'RAG, Retrieval & Grounding', 'Khó', 'Query ''quy định nghỉ phép cho nhân viên mới ở chi nhánh A'' vừa mơ hồ vừa multi-hop. Chiến lược nào hợp?', 'C', 'Cần mở rộng thuật ngữ, chia sub-query và lọc domain/region để tăng recall có kiểm soát.', '**query expansion**: mở rộng query bằng từ đồng nghĩa, thuật ngữ hoặc biến thể để tăng recall.; **metadata**: siêu dữ liệu như nguồn, loại, ngày, khu vực hoặc quyền của một chunk.; **recall**: tỷ lệ các trường hợp đúng mà hệ thống tìm được.'),
(203, 1, 203, 'RAG, Retrieval & Grounding', 'Khó', 'HyDE sinh câu trả lời giả định có thể sai. Vì sao vẫn dùng vector của nó để retrieve?', 'D', 'HyDE là query transformation; evidence thật vẫn phải đến từ tài liệu retrieved.', '**HyDE**: Hypothetical Document Embeddings — tạo văn bản giả định để đưa query gần không gian tài liệu.'),
(204, 1, 204, 'RAG, Retrieval & Grounding', 'Khó', 'Hybrid score dense và BM25 khác thang đo. RRF có lợi thế gì?', 'A', 'RRF dùng vị trí xếp hạng và tránh bài toán ''cam và táo'' giữa hai score.', '**BM25**: thuật toán sparse search chấm mức phù hợp của từ khóa trong tài liệu.; **RRF**: Reciprocal Rank Fusion — gộp kết quả dựa trên thứ hạng từ nhiều retriever.'),
(205, 1, 205, 'RAG, Retrieval & Grounding', 'Khó', 'Reranker đưa ba chunk gần như cùng nội dung lên đầu. Kỹ thuật nào nên thêm?', 'B', 'Cross-encoder tối ưu relevance; MMR bổ sung mục tiêu diversity khi các kết quả trùng.', '**cross-encoder**: model đọc query và document cùng nhau để chấm relevance chính xác hơn.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **MMR**: Maximum Marginal Relevance — cân bằng relevance với độ đa dạng, giảm chunk trùng lặp.'),
(206, 1, 206, 'RAG, Retrieval & Grounding', 'Khó', 'Retrieved context tốt nhưng nằm giữa prompt quá dài và model bỏ qua. Thay đổi nào hợp lý?', 'C', 'Giảm nhiễu và đặt evidence quan trọng ở vị trí được chú ý hơn cải thiện generation.', '**generation**: tạo sinh; bước LLM tổng hợp câu trả lời từ context đã truy xuất.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(207, 1, 207, 'RAG, Retrieval & Grounding', 'Khó', 'Hai tài liệu nói 12 và 14 ngày nghỉ phép. Generation grounded cần làm gì?', 'D', 'Conflict resolution cần version/effective date; nếu không giải quyết được, agent nên nói rõ giới hạn.', '**generation**: tạo sinh; bước LLM tổng hợp câu trả lời từ context đã truy xuất.; **metadata**: siêu dữ liệu như nguồn, loại, ngày, khu vực hoặc quyền của một chunk.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(208, 1, 208, 'RAG, Retrieval & Grounding', 'Khó', 'RAGAS Context Recall thấp nhưng Faithfulness cao. Diễn giải nào đúng?', 'A', 'Context recall đo độ phủ evidence; faithfulness đo output có bám context đã nhận hay không.', '**context recall**: mức độ retriever mang về đủ evidence cần thiết để trả lời.; **faithfulness**: mức độ câu trả lời bám trung thực vào context được truy xuất.; **evaluation**: đánh giá chất lượng hệ thống trên bộ case và tiêu chí đã định.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **recall**: tỷ lệ các trường hợp đúng mà hệ thống tìm được.; **RAGAS**: framework/nhóm metric đánh giá RAG, thường gồm context recall, faithfulness và answer relevance.'),
(209, 1, 209, 'RAG, Retrieval & Grounding', 'Khó', 'Formatted context không chứa đáp án nhưng model vẫn trả lời tự tin. Sửa tầng nào trước?', 'B', 'Nếu evidence không vào context, generation không thể grounded; cần sửa retrieval trước.', '**generation**: tạo sinh; bước LLM tổng hợp câu trả lời từ context đã truy xuất.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **indexing**: lập chỉ mục; parse, clean, chunk, embed và lưu tài liệu để tìm kiếm.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.'),
(210, 1, 210, 'RAG, Retrieval & Grounding', 'Khó', 'Golden dataset tốt cho RAG cần có đặc điểm nào?', 'C', 'Bộ câu hỏi vàng giúp A/B test indexing, retrieval, prompt và model trên cùng chuẩn.', '**golden dataset**: bộ câu hỏi và đáp án/evidence chuẩn dùng làm mốc đánh giá.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **indexing**: lập chỉ mục; parse, clean, chunk, embed và lưu tài liệu để tìm kiếm.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **RAG**: Retrieval-Augmented Generation — tạo sinh tăng cường bằng truy xuất tài liệu.'),
(211, 1, 211, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'Khi nào single-agent có thể bắt đầu quá tải?', 'B', 'Context bottleneck và quá nhiều trách nhiệm là dấu hiệu cân nhắc multi-agent.', '**multi-agent**: hệ nhiều agent được phân vai và phối hợp cho cùng một nhiệm vụ.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(212, 1, 212, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'Multi-agent chủ yếu nhằm đạt lợi ích nào?', 'C', 'Multi-agent không mặc định tốt hơn; giá trị là phân vai hợp lý cho bài toán phức tạp.', '**multi-agent**: hệ nhiều agent được phân vai và phối hợp cho cùng một nhiệm vụ.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(213, 1, 213, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'Supervisor trong pattern supervisor-worker làm gì?', 'D', 'Supervisor chịu trách nhiệm điều phối, còn worker xử lý năng lực hẹp hơn.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.'),
(214, 1, 214, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'Worker tốt trong hệ multi-agent nên có đặc điểm nào?', 'A', 'Worker hẹp giúp route rõ, dễ test và dễ xác định lỗi.', '**multi-agent**: hệ nhiều agent được phân vai và phối hợp cho cùng một nhiệm vụ.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(215, 1, 215, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'MCP giải quyết vấn đề tích hợp nào?', 'C', 'MCP giảm việc viết adapter riêng cho từng tool và tạo giao thức client/server thống nhất.', '**agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **MCP**: Model Context Protocol — chuẩn kết nối agent với tools và resources bên ngoài.'),
(216, 1, 216, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'MCP server có thể công bố loại capability nào?', 'D', 'Tools phục vụ hành động; resources cung cấp dữ liệu hoặc tài nguyên để đọc.', '**agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **MCP**: Model Context Protocol — chuẩn kết nối agent với tools và resources bên ngoài.'),
(217, 1, 217, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'A2A khác MCP ở điểm nào?', 'A', 'Slide nhấn mạnh MCP là agent–tool, còn A2A là agent–agent communication.', '**agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **MCP**: Model Context Protocol — chuẩn kết nối agent với tools và resources bên ngoài.; **A2A**: Agent-to-Agent — giao tiếp giữa các agent qua message contract.'),
(218, 1, 218, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'Message contract trong A2A giúp điều gì?', 'B', 'Contract rõ giảm context thiếu, output lệch và số lần supervisor phải gọi lại.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **A2A**: Agent-to-Agent — giao tiếp giữa các agent qua message contract.'),
(219, 1, 219, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'Shared state trong graph thường dùng để lưu gì?', 'D', 'State là vùng thông tin chung giúp nodes phối hợp trong một workflow.', '**shared state**: trạng thái dùng chung giữa các node/agent trong một workflow.; **workflow**: quy trình gồm các bước và bàn giao để hoàn thành một công việc.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(220, 1, 220, 'Multi-Agent, MCP, A2A & LangGraph', 'Dễ', 'Trong LangGraph, node thường là gì?', 'C', 'LangGraph mô hình hóa logic bằng nodes, edges và state.', '**LangGraph**: framework biểu diễn workflow agent bằng state, node, edge và conditional routing.'),
(221, 1, 221, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Một task cần planner, retriever và synthesizer. Supervisor nên làm gì?', 'B', 'Phân vai rõ giúp route, debug và kiểm tra từng giai đoạn.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(222, 1, 222, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Hai worker tra hai nguồn độc lập có thể tối ưu latency bằng cách nào?', 'C', 'Task độc lập phù hợp parallel execution, nhưng vẫn cần schema và timeout rõ.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(223, 1, 223, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Shared state tiện hơn message passing khi nào?', 'D', 'Shared state thuận tiện cho graph orchestration; message passing có thể cách ly tốt hơn giữa các thành phần.', '**shared state**: trạng thái dùng chung giữa các node/agent trong một workflow.'),
(224, 1, 224, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'MCP tool discovery thường bắt đầu bằng bước nào?', 'A', 'Luồng discovery giúp client biết danh sách, mô tả và schema tool mà server công bố.', '**MCP**: Model Context Protocol — chuẩn kết nối agent với tools và resources bên ngoài.'),
(225, 1, 225, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Message contract thiếu output schema dễ gây hậu quả nào?', 'B', 'Contract cần nêu nhiệm vụ, context, format và bằng chứng để worker trả kết quả dùng được.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **A2A**: Agent-to-Agent — giao tiếp giữa các agent qua message contract.'),
(226, 1, 226, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Sync A2A phù hợp hơn async khi nào?', 'C', 'Sync đơn giản để hiểu và debug khi luồng cần kết quả trước khi tiếp tục.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **A2A**: Agent-to-Agent — giao tiếp giữa các agent qua message contract.'),
(227, 1, 227, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Boundary security giữa các agent nên kiểm soát điều gì?', 'D', 'Quyền và dữ liệu cần giới hạn; worker chạm external tool phải có validation.', '**worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(228, 1, 228, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Conditional edge trong LangGraph hữu ích thế nào?', 'A', 'Router/conditional edge cho phép graph rẽ nhánh theo tool call, trạng thái hoặc điều kiện kết thúc.', '**LangGraph**: framework biểu diễn workflow agent bằng state, node, edge và conditional routing.'),
(229, 1, 229, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Trace multi-agent nên ghi thêm trường nào để debug routing?', 'B', 'Trace cần cho biết ai nhận gì, được gọi vì sao và trả kết quả nào.', '**multi-agent**: hệ nhiều agent được phân vai và phối hợp cho cùng một nhiệm vụ.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(230, 1, 230, 'Multi-Agent, MCP, A2A & LangGraph', 'Vừa', 'Nếu thêm worker nhưng cost và latency tăng mà chất lượng không cải thiện, kết luận nào hợp lý?', 'D', 'Multi-agent là trade-off; số agent không phải thước đo chất lượng.', '**multi-agent**: hệ nhiều agent được phân vai và phối hợp cho cùng một nhiệm vụ.; **latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(231, 1, 231, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'Một single-agent phải đọc hợp đồng 80 trang, tra luật, gọi API và viết risk summary. Dấu hiệu chia agent mạnh nhất là gì?', 'B', 'Context bottleneck, nhiều vai trò và nhu cầu truy nguyên lỗi là lý do thực dụng để phân chia.', '**context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(232, 1, 232, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'Một pipeline luôn chạy Parser → Research → Synthesis. Pattern nào phù hợp hơn supervisor động?', 'C', 'Pipeline dành cho flow tuyến tính; supervisor phù hợp khi route/subtask thay đổi theo input.', '**multi-agent**: hệ nhiều agent được phân vai và phối hợp cho cùng một nhiệm vụ.; **supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(233, 1, 233, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'Supervisor trở thành ''god supervisor'' khi nào?', 'D', 'Supervisor quá tải làm mất lợi ích phân vai và trở lại single-agent khó debug.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(234, 1, 234, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'Shared state chứa PII nhưng worker chỉ cần một kết luận đã mask. Thiết kế nào an toàn hơn?', 'A', 'Message passing và data minimization giảm blast radius so với chia toàn bộ state.', '**shared state**: trạng thái dùng chung giữa các node/agent trong một workflow.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **PII**: Personally Identifiable Information — dữ liệu có thể nhận diện một cá nhân.'),
(235, 1, 235, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'MCP server công bố tool nhưng client không biết tham số bắt buộc. Lỗi nằm ở đâu?', 'B', 'MCP client cần tools/list và schema để biết cách gọi; contract không rõ dẫn đến arguments sai.', '**MCP**: Model Context Protocol — chuẩn kết nối agent với tools và resources bên ngoài.'),
(236, 1, 236, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'A2A worker trả ''đã tìm policy'' nhưng không có source, rank hay status. Vì sao supervisor khó tin?', 'C', 'Contract cần định nghĩa output có thể tổng hợp và audit, không chỉ một câu mô tả chung.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **A2A**: Agent-to-Agent — giao tiếp giữa các agent qua message contract.'),
(237, 1, 237, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'Worker nghiên cứu chạy 20 phút, supervisor không cần kết quả ngay. Giao tiếp nào phù hợp?', 'D', 'Async tách vòng đời task dài khỏi request và cho phép theo dõi trạng thái.', '**supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.'),
(238, 1, 238, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'Graph route worker dựa trên need_retrieval và last message. Nếu route sai lặp lại, cần inspect gì?', 'A', 'Routing lỗi có thể do field state, prompt router hoặc điều kiện edge; trace giúp phân biệt.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **LangGraph**: framework biểu diễn workflow agent bằng state, node, edge và conditional routing.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.'),
(239, 1, 239, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'Multi-agent khó debug hơn single-agent chủ yếu vì sao?', 'B', 'Nhiều boundary tạo nhiều điểm hỏng; trace cần ghi agent_id, input, output và status.', '**observability**: khả năng hiểu trạng thái nội bộ hệ thống từ metrics, logs, traces và eval.; **multi-agent**: hệ nhiều agent được phân vai và phối hợp cho cùng một nhiệm vụ.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(240, 1, 240, 'Multi-Agent, MCP, A2A & LangGraph', 'Khó', 'Nếu workers độc lập chạy song song nhưng supervisor retry toàn bộ khi một worker lỗi, cải tiến nào hợp lý?', 'D', 'Granular retry giảm cost/latency và tránh lặp side effect của nhánh đã thành công.', '**side effect**: tác động bên ngoài như gửi email, xóa dữ liệu, trừ tiền hoặc đặt vé.; **supervisor**: agent điều phối; route task tới worker và tổng hợp kết quả.; **latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **worker**: agent chuyên trách một năng lực hẹp như retrieve, gọi tool hoặc summarize.'),
(241, 1, 241, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'ETL khác ELT chủ yếu ở thứ tự nào?', 'B', 'Cả hai đều có Extract, Transform và Load; điểm khác là vị trí transform.', '**ETL**: Extract–Transform–Load — lấy, biến đổi rồi nạp dữ liệu.; **ELT**: Extract–Load–Transform — lấy, nạp raw trước rồi biến đổi trong kho đích.'),
(242, 1, 242, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'Batch processing có đặc điểm nào?', 'C', 'Batch phù hợp khi có thể chấp nhận độ trễ và muốn vận hành theo lịch.', '**streaming**: trả kết quả từng phần ngay khi sinh, thay vì chờ toàn bộ output.; **batch**: xử lý dữ liệu theo lô vào thời điểm định trước.'),
(243, 1, 243, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'Streaming phù hợp hơn batch khi nào?', 'D', 'Streaming xử lý dòng event liên tục và giảm độ trễ so với chạy theo lô.', '**streaming**: trả kết quả từng phần ngay khi sinh, thay vì chờ toàn bộ output.; **batch**: xử lý dữ liệu theo lô vào thời điểm định trước.'),
(244, 1, 244, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'CDC dùng để làm gì trong ingestion database?', 'A', 'Change Data Capture ghi nhận thay đổi thay vì quét lại toàn bộ bảng mỗi lần.', '**snapshot**: ảnh chụp dữ liệu tại một thời điểm, thường dùng để quét theo lịch.; **CDC**: Change Data Capture — ghi nhận các bản ghi được tạo, sửa hoặc xóa.'),
(245, 1, 245, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'Exponential backoff xử lý lỗi 429 như thế nào?', 'C', 'Backoff giảm áp lực lên dịch vụ đang giới hạn tốc độ; jitter giúp tránh retry đồng thời.', '**exponential backoff**: tăng dần thời gian chờ giữa các lần retry, thường theo cấp số nhân.; **jitter**: độ ngẫu nhiên nhỏ cộng vào thời gian retry để tránh nhiều client retry cùng lúc.'),
(246, 1, 246, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'Cursor pagination có ưu điểm nào so với offset khi dữ liệu đổi?', 'D', 'Cursor tiếp tục từ dấu mốc ổn định hơn khi dữ liệu nguồn thay đổi trong lúc đọc.', '**pagination**: chia kết quả lớn thành nhiều trang hoặc batch nhỏ để đọc tuần tự.'),
(247, 1, 247, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'DLQ trong pipeline thường chứa gì?', 'A', 'Dead-letter queue giữ message không xử lý được để không chặn toàn bộ dòng dữ liệu.', '**dead-letter queue**: DLQ — hàng đợi chứa message xử lý thất bại để điều tra hoặc replay.'),
(248, 1, 248, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'Data contract giúp pipeline biết điều gì?', 'B', 'Data contract là thỏa thuận có thể kiểm tra giữa nguồn và bên nhận dữ liệu.', '**data contract**: thỏa thuận về schema, kiểu dữ liệu, giá trị hợp lệ và trách nhiệm giữa các bên.'),
(249, 1, 249, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'Drift nói lên điều gì?', 'D', 'Drift là tín hiệu cần điều tra; nó không tự kết luận dữ liệu mới đúng hay sai.', '**drift**: sự thay đổi phân phối dữ liệu hoặc hành vi so với mốc tham chiếu.'),
(250, 1, 250, 'Data Pipeline, Quality & Data Observability', 'Dễ', 'Idempotency trong pipeline giúp điều gì?', 'C', 'Upsert theo natural key như doc_id và version giúp lần chạy lại không nhân đôi dữ liệu.', '**idempotency**: tính lặp an toàn; chạy lại cùng request không tạo thêm side effect hoặc bản ghi trùng.'),
(251, 1, 251, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Team cần governance mạnh trước khi nạp dữ liệu vào warehouse. ETL có thể phù hợp vì sao?', 'B', 'ETL lọc và chuẩn hóa sớm; ELT giữ raw để transform sau, thường linh hoạt hơn cho warehouse.', '**ETL**: Extract–Transform–Load — lấy, biến đổi rồi nạp dữ liệu.; **ELT**: Extract–Load–Transform — lấy, nạp raw trước rồi biến đổi trong kho đích.'),
(252, 1, 252, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Tồn kho cần cập nhật gần ngay sau mỗi thay đổi. Lựa chọn nào hợp lý?', 'C', 'Operational freshness cao ưu tiên event-driven ingestion hơn batch chậm.', '**streaming**: trả kết quả từng phần ngay khi sinh, thay vì chờ toàn bộ output.; **freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.; **batch**: xử lý dữ liệu theo lô vào thời điểm định trước.; **CDC**: Change Data Capture — ghi nhận các bản ghi được tạo, sửa hoặc xóa.'),
(253, 1, 253, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'CDC có lợi thế gì so với snapshot khi bảng lớn và thay đổi ít?', 'D', 'CDC tiết kiệm công đọc và truyền dữ liệu, nhưng phải xử lý đầy đủ create/update/delete.', '**snapshot**: ảnh chụp dữ liệu tại một thời điểm, thường dùng để quét theo lịch.; **CDC**: Change Data Capture — ghi nhận các bản ghi được tạo, sửa hoặc xóa.'),
(254, 1, 254, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Khi API trả 429 kèm Retry-After, retry policy nên ưu tiên gì?', 'A', 'Retry-After là tín hiệu từ server; exponential backoff và jitter tránh tạo bão retry.', '**exponential backoff**: tăng dần thời gian chờ giữa các lần retry, thường theo cấp số nhân.; **jitter**: độ ngẫu nhiên nhỏ cộng vào thời gian retry để tránh nhiều client retry cùng lúc.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(255, 1, 255, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Offset pagination dễ làm lặp bản ghi khi nào?', 'B', 'Offset phụ thuộc vị trí; dữ liệu đổi có thể đẩy dòng sang trang trước hoặc sau.', '**pagination**: chia kết quả lớn thành nhiều trang hoặc batch nhỏ để đọc tuần tự.'),
(256, 1, 256, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Content hash khác logical version ở điểm nào?', 'C', 'File có thể đổi bytes nhưng giữ version; hoặc version đổi mà bytes xử lý không như mong muốn.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(257, 1, 257, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Backpressure cần thiết khi producer nhanh hơn consumer vì sao?', 'D', 'Queue, giới hạn tốc độ hoặc pause producer bảo vệ consumer khi lưu lượng tăng.', '**backpressure**: cơ chế làm chậm producer khi consumer hoặc downstream quá tải.'),
(258, 1, 258, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Một cột vẫn đúng type nhưng null rate tăng mạnh. Nên kiểm tra dimension nào?', 'A', 'Schema có thể pass nhưng dữ liệu thiếu; cần theo dõi completeness và nguyên nhân upstream.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(259, 1, 259, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Agent trả lời policy cũ dù pipeline job không báo lỗi. Triage đầu tiên nên xem gì?', 'B', 'Job thành công nhưng không có dữ liệu mới có thể là freshness hoặc publish/cache swap lỗi.', '**freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(260, 1, 260, 'Data Pipeline, Quality & Data Observability', 'Vừa', 'Quality gate nên làm gì khi dữ liệu vi phạm rule nghiêm trọng?', 'D', 'Gate là điểm quyết định; dữ liệu nguy hiểm cần bị chặn và có dấu vết xử lý.', '**quality gate**: điểm kiểm tra quyết định dữ liệu có được đi tiếp, quarantine hoặc dừng pipeline.'),
(261, 1, 261, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Một lỗi parser làm chunk ngắn bất thường, retrieval sai và agent trả policy cũ. Đây là mẫu lỗi nào?', 'B', 'Một quyết định/lỗi đầu nguồn có thể làm hậu quả lớn dần qua các tầng.', '**retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(262, 1, 262, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Nguồn cần lưu raw để audit nhưng warehouse biến đổi linh hoạt sau khi load. ELT có lợi thế nào?', 'C', 'ELT phù hợp khi warehouse có khả năng xử lý và cần giữ raw; quality gate downstream vẫn cần.', '**quality gate**: điểm kiểm tra quyết định dữ liệu có được đi tiếp, quarantine hoặc dừng pipeline.; **ETL**: Extract–Transform–Load — lấy, biến đổi rồi nạp dữ liệu.; **ELT**: Extract–Load–Transform — lấy, nạp raw trước rồi biến đổi trong kho đích.'),
(263, 1, 263, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Snapshot job báo thành công nhưng lấy 0 dòng vì watermark sai. Metric nào nên phát hiện?', 'D', 'Không có row mới có thể trông như success; volume và freshness phải có threshold.', '**threshold**: ngưỡng điểm dùng để loại kết quả có mức liên quan quá thấp.; **freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.; **snapshot**: ảnh chụp dữ liệu tại một thời điểm, thường dùng để quét theo lịch.'),
(264, 1, 264, 'Data Pipeline, Quality & Data Observability', 'Khó', 'CDC nhận update rồi delete nhưng consumer chỉ xử lý upsert. Hậu quả là gì?', 'A', 'CDC phải truyền và xử lý semantics của delete, không chỉ create/update.', '**CDC**: Change Data Capture — ghi nhận các bản ghi được tạo, sửa hoặc xóa.'),
(265, 1, 265, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Một dataset có duplicate id, ngày tháng sai kiểu và nhiều NULL. Cách phân loại dimension nào hợp?', 'B', 'Data quality dimensions cần tách câu hỏi: không trùng, đúng kiểu/giá trị và đủ dữ liệu.', 'Không có thuật ngữ tiếng Anh chuyên môn mới cần giải thích trong câu này.'),
(266, 1, 266, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Drift tăng sau khi nguồn thay đổi nhưng accuracy chưa biết. Quyết định nào đúng?', 'C', 'Drift chỉ báo phân phối lệch baseline; cần rule/domain knowledge để phán định.', '**baseline**: mốc chuẩn dùng để so sánh với cách làm hiện tại.; **drift**: sự thay đổi phân phối dữ liệu hoặc hành vi so với mốc tham chiếu.'),
(267, 1, 267, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Agent trả fact cũ lúc 09:12. Theo thứ tự triage slide, nên mở dashboard nào trước?', 'D', 'Day 10 nêu thứ tự Freshness → Volume → Schema → Lineage để khoanh tầng dữ liệu.', '**freshness**: độ mới của dữ liệu so với thời điểm user cần sử dụng.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(268, 1, 268, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Pipeline chạy lại cùng doc_id/version nhưng tạo UUID mới và duplicate chunk. Thiết kế nào thiếu?', 'A', 'Natural key như (doc_id, version) giúp retry ghi đè đúng bản ghi thay vì tạo bản sao.', '**idempotency**: tính lặp an toàn; chạy lại cùng request không tạo thêm side effect hoặc bản ghi trùng.'),
(269, 1, 269, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Một rule chặn 2% dòng nhưng không có owner hoặc lý do. Vấn đề governance nào phát sinh?', 'B', 'Data contract và RACI giúp rule có owner, artifact và quyết định chấp nhận rủi ro.', '**data contract**: thỏa thuận về schema, kiểu dữ liệu, giá trị hợp lệ và trách nhiệm giữa các bên.; **quality gate**: điểm kiểm tra quyết định dữ liệu có được đi tiếp, quarantine hoặc dừng pipeline.; **RACI**: ma trận Responsible, Accountable, Consulted, Informed để phân trách nhiệm.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(270, 1, 270, 'Data Pipeline, Quality & Data Observability', 'Khó', 'Một event lỗi retry nhiều lần rồi làm queue nghẽn. Thiết kế nào giảm tác động?', 'C', 'DLQ cô lập poison message; alert và replay có kiểm soát bảo vệ pipeline chính.', '**DLQ**: Dead-Letter Queue — hàng đợi cách ly event lỗi.'),
(271, 1, 271, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'Guardrails tồn tại để làm gì?', 'B', 'Guardrails là lớp kiểm soát bắt buộc khi agent có dữ liệu, tool hoặc hành động thực tế.', '**guardrails**: hàng rào kiểm soát; các lớp giới hạn input, model, output và hành động rủi ro.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(272, 1, 272, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'Input guardrail thường chạy ở thời điểm nào?', 'C', 'Input rails có thể kiểm tra độ dài, format, topic và dấu hiệu prompt injection.', '**prompt injection**: tấn công chèn instruction để thao túng hoặc ghi đè chỉ dẫn của agent.; **guardrails**: hàng rào kiểm soát; các lớp giới hạn input, model, output và hành động rủi ro.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(273, 1, 273, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'Output guardrail kiểm tra điều gì?', 'D', 'Output rails là tuyến cuối để redact, block hoặc yêu cầu kiểm tra lại response.', '**guardrails**: hàng rào kiểm soát; các lớp giới hạn input, model, output và hành động rủi ro.; **grounding**: neo câu trả lời vào evidence được cung cấp, không tự suy diễn ngoài nguồn.; **PII**: Personally Identifiable Information — dữ liệu có thể nhận diện một cá nhân.'),
(274, 1, 274, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'Defense in depth nghĩa là gì trong AI safety?', 'A', 'Input rails, LLM rails, output rails và human review bổ sung cho nhau.', '**defense in depth**: phòng thủ nhiều lớp; không phụ thuộc vào một bộ lọc duy nhất.; **LLM**: Large Language Model — mô hình ngôn ngữ lớn.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(275, 1, 275, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'Red teaming là hoạt động nào?', 'C', 'Red team tấn công có chủ đích để kiểm tra guardrails trước khi người xấu làm.', '**red teaming**: kiểm thử đối kháng bằng cách chủ động tấn công hệ thống để tìm lỗ hổng.; **guardrails**: hàng rào kiểm soát; các lớp giới hạn input, model, output và hành động rủi ro.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(276, 1, 276, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'HITL phù hợp nhất với hành động nào?', 'D', 'Human-in-the-loop thêm phê duyệt cho hành động khó hoàn tác hoặc high-stakes.', '**HITL**: Human-in-the-Loop — con người duyệt hoặc can thiệp tại điểm rủi ro.'),
(277, 1, 277, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'Vì sao production nên dùng environment variables cho secrets?', 'A', '12-Factor App tách config và secret khỏi code để dễ bảo vệ, thay đổi và triển khai.', '**environment variables**: biến môi trường dùng để cấp config/secrets mà không hardcode vào code.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(278, 1, 278, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'Health check endpoint giúp hệ thống biết điều gì?', 'B', 'Liveness và readiness probe hỗ trợ restart hoặc loại instance lỗi khỏi traffic.', '**health check**: endpoint/probe kiểm tra container còn sống hoặc sẵn sàng nhận request.'),
(279, 1, 279, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'Ba pillar truyền thống của observability là gì?', 'D', 'Day 13 bổ sung continuous eval như pillar thứ tư riêng cho AI.', '**observability**: khả năng hiểu trạng thái nội bộ hệ thống từ metrics, logs, traces và eval.; **metrics**: số đo định lượng theo thời gian như latency, error rate, token hoặc cost.; **traces**: dấu vết end-to-end cho thấy một request đi qua các bước nào và mất bao lâu.; **logs**: bản ghi sự kiện chi tiết của hệ thống, thường dùng để tìm nguyên nhân lỗi.; **eval**: viết tắt của evaluation — đánh giá chất lượng AI.; **AI**: Artificial Intelligence — trí tuệ nhân tạo.'),
(280, 1, 280, 'Guardrails, Safety, Deployment & Observability', 'Dễ', 'P99 latency mô tả điều gì?', 'C', 'Percentile cao cho thấy trải nghiệm của nhóm request chậm, thường quan trọng trong agent.', '**latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **P99**: percentile 99; cho thấy tail latency của nhóm request chậm nhất.'),
(281, 1, 281, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'User gõ ''ignore previous instructions'' là tấn công nào?', 'B', 'Chỉ dẫn độc hại nằm trực tiếp trong input user và cố ghi đè system prompt.', '**direct prompt injection**: prompt injection nằm trực tiếp trong input của user.; **prompt injection**: tấn công chèn instruction để thao túng hoặc ghi đè chỉ dẫn của agent.; **system prompt**: chỉ dẫn nền do ứng dụng đặt để định nghĩa vai trò, luật và capability của model.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.'),
(282, 1, 282, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'Tài liệu PDF có hidden text ra lệnh gửi dữ liệu cho hacker là tấn công nào?', 'C', 'Instruction nằm trong nội dung mà agent retrieve, không nằm trực tiếp trong câu hỏi user.', '**indirect prompt injection**: prompt injection ẩn trong tài liệu, web hoặc tool output mà agent đọc.; **prompt injection**: tấn công chèn instruction để thao túng hoặc ghi đè chỉ dẫn của agent.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(283, 1, 283, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'Nếu agent có quyền xóa database, guardrail kỹ thuật quan trọng là gì?', 'D', 'Giới hạn quyền giảm blast radius nếu model hoặc tool output bị thao túng.', '**least privilege**: nguyên tắc chỉ cấp đúng quyền tối thiểu cần cho agent hoặc service.; **sandbox**: môi trường cách ly để giới hạn quyền và tác động của code/tool.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(284, 1, 284, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'HITL model nào hợp với việc publish nội dung công khai?', 'A', 'Publish có side effect và rủi ro danh tiếng; nên phê duyệt trước khi thực hiện.', '**side effect**: tác động bên ngoài như gửi email, xóa dữ liệu, trừ tiền hoặc đặt vé.; **HITL**: Human-in-the-Loop — con người duyệt hoặc can thiệp tại điểm rủi ro.'),
(285, 1, 285, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'Multi-stage Docker build đem lại lợi ích nào?', 'B', 'Builder chứa công cụ build; runtime image chỉ giữ dependency cần chạy.', '**Docker**: công cụ đóng gói ứng dụng và dependency thành container có thể chạy nhất quán.'),
(286, 1, 286, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'Agent reasoning vượt timeout gateway. Giải pháp UX/infrastructure nào phù hợp?', 'C', 'SSE báo tiến trình sớm; task dài nên chuyển queue/job để không giữ HTTP request quá lâu.', '**streaming**: trả kết quả từng phần ngay khi sinh, thay vì chờ toàn bộ output.; **reasoning**: suy luận; phân tích mục tiêu và chọn bước tiếp theo.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **task**: nhiệm vụ cụ thể mà prompt yêu cầu model hoàn thành.; **UX**: User Experience — trải nghiệm người dùng khi tương tác với sản phẩm.'),
(287, 1, 287, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'Để agent vừa stateless vừa giữ conversation, nên làm gì?', 'D', 'External state cho phép load balancer phân request sang nhiều instance.', '**stateless**: không giữ state phiên trong instance; state thường được lưu ở hệ thống bên ngoài.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(288, 1, 288, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'API gateway trước agent thường nên có ba lớp bảo vệ nào?', 'A', 'Gateway lọc quyền truy cập, tốc độ và ngân sách trước khi request chạm logic agent.', '**API gateway**: cổng trước backend để xác thực, giới hạn tốc độ và bảo vệ chi phí.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(289, 1, 289, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'Structured JSON log nên có correlation_id để làm gì?', 'B', 'Correlation ID giúp đi từ request đến LLM call, tool call và lỗi liên quan.', '**LLM**: Large Language Model — mô hình ngôn ngữ lớn.'),
(290, 1, 290, 'Guardrails, Safety, Deployment & Observability', 'Vừa', 'SLO khác SLA ở điểm nào?', 'D', 'SLI là số đo; SLO là mục tiêu nội bộ; SLA là cam kết dịch vụ với hệ quả nếu vi phạm.', '**SLI**: Service Level Indicator — chỉ số đo dịch vụ, ví dụ phần trăm request dưới 5 giây.; **SLO**: Service Level Objective — mục tiêu chất lượng/độ tin cậy cần đạt.; **SLA**: Service Level Agreement — cam kết dịch vụ với người dùng hoặc khách hàng.'),
(291, 1, 291, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Agent vừa đọc dữ liệu riêng, vừa nhận nội dung web không tin cậy, vừa có quyền gửi email. Vì sao đây là lethal trifecta?', 'B', 'Private data, untrusted content và external side effect kết hợp làm blast radius lớn.', '**side effect**: tác động bên ngoài như gửi email, xóa dữ liệu, trừ tiền hoặc đặt vé.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(292, 1, 292, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Input classifier bắt được direct injection nhưng indirect injection vẫn lọt. Lớp nào nên bổ sung?', 'C', 'Filter đơn lẻ dễ bị bypass; defense in depth và tách data/instruction xử lý nội dung retrieved.', '**defense in depth**: phòng thủ nhiều lớp; không phụ thuộc vào một bộ lọc duy nhất.; **grounding**: neo câu trả lời vào evidence được cung cấp, không tự suy diễn ngoài nguồn.'),
(293, 1, 293, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Action-Selector Agent giảm risk bằng cách nào?', 'D', 'Giới hạn action space và tách selector khỏi executor làm giảm quyền tự do nguy hiểm.', '**action**: hành động được agent chọn để tiến tới mục tiêu.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(294, 1, 294, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Gửi tiền và xóa dữ liệu là hành động high-stakes. HITL architecture hợp lý nhất là gì?', 'A', 'Human-in-the-loop trước hành động không thể hoàn tác, cùng least privilege và audit log.', '**least privilege**: nguyên tắc chỉ cấp đúng quyền tối thiểu cần cho agent hoặc service.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **HITL**: Human-in-the-Loop — con người duyệt hoặc can thiệp tại điểm rủi ro.'),
(295, 1, 295, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Docker image chứa API key trong layer cũ dù file cuối đã xóa. Cách phòng ngừa là gì?', 'B', '12-Factor tách secret khỏi image; scan và secret manager giảm nguy cơ rò rỉ trong layer.', '**Docker**: công cụ đóng gói ứng dụng và dependency thành container có thể chạy nhất quán.; **API**: Application Programming Interface — giao diện để phần mềm gửi yêu cầu và nhận kết quả từ dịch vụ.'),
(296, 1, 296, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Agent giữ conversation trong RAM instance và có load balancer. Tại sao request sau có thể mất context?', 'C', 'Stateful process khó scale ngang; external session store giải quyết affinity và durability.', '**stateless**: không giữ state phiên trong instance; state thường được lưu ở hệ thống bên ngoài.; **context**: bối cảnh hoặc dữ liệu nền được đưa cho model để xử lý task.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(297, 1, 297, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Agent gửi email rồi crash trước khi ghi kết quả. Retry từ đầu nguy hiểm vì sao?', 'D', 'Idempotency key, durable execution hoặc saga giúp tránh lặp side effect.', '**idempotency**: tính lặp an toàn; chạy lại cùng request không tạo thêm side effect hoặc bản ghi trùng.; **side effect**: tác động bên ngoài như gửi email, xóa dữ liệu, trừ tiền hoặc đặt vé.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.'),
(298, 1, 298, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'P50 latency vẫn 2 giây nhưng P99 tăng từ 5 lên 12 giây. Tác động production nào cần chú ý?', 'A', 'Percentile cao cho thấy tail latency; agent nhiều lượt làm xác suất gặp một request chậm tăng.', '**latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **agent**: hệ thống dùng model để lập kế hoạch, gọi tool, quan sát kết quả và lặp đến khi hoàn thành mục tiêu.; **P50**: percentile 50; khoảng một nửa request nhanh hơn hoặc bằng mốc này.; **P99**: percentile 99; cho thấy tail latency của nhóm request chậm nhất.'),
(299, 1, 299, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Structured logging log raw prompt chứa CCCD và dùng request_id làm metric label. Hai rủi ro là gì?', 'B', 'Raw PII cần redact/allowlist; label tự do như request_id tạo quá nhiều time series.', '**cardinality**: số lượng tổ hợp giá trị của label; quá cao làm metric tốn storage và khó vận hành.; **prompt**: chỉ dẫn hoặc đầu vào bằng ngôn ngữ tự nhiên gửi cho model.; **PII**: Personally Identifiable Information — dữ liệu có thể nhận diện một cá nhân.'),
(300, 1, 300, 'Guardrails, Safety, Deployment & Observability', 'Khó', 'Error rate bình thường nhưng P95 latency tăng đột ngột; trace cho thấy retrieval quét toàn index sau deploy. Fix nào đúng tầng?', 'C', 'Trace chỉ ra bottleneck retrieval; sửa hạ tầng/query và bổ sung eval/observability để tránh tái diễn.', '**observability**: khả năng hiểu trạng thái nội bộ hệ thống từ metrics, logs, traces và eval.; **retrieval**: truy xuất; tìm các chunk liên quan từ kho dữ liệu.; **latency**: độ trễ; thời gian từ lúc gửi yêu cầu đến khi nhận kết quả.; **eval**: viết tắt của evaluation — đánh giá chất lượng AI.; **P95**: percentile 95; khoảng 95% request nhanh hơn hoặc bằng mốc này.')
